/* Shared quiz question bank. */
window.questionBank = [
            { id: "programming-1", category: "programming", difficulty: "easy", question: "Apa fungsi variabel dalam program?", answers: ["Menyimpan nilai yang bisa digunakan ulang", "Menghapus error otomatis", "Mengubah desain database", "Menjalankan internet"], correct: 0, hint: "Bayangkan kotak bernama yang berisi data.", explanation: "Variabel dipakai untuk menyimpan nilai, lalu nilai itu dapat dibaca atau diubah selama program berjalan." },
            { id: "programming-2", category: "programming", difficulty: "easy", question: "Apa arti tipe data boolean?", answers: ["Nilai benar atau salah", "Daftar gambar", "Koneksi server", "Ukuran layar"], correct: 0, hint: "Biasanya bernilai true atau false.", explanation: "Boolean digunakan untuk kondisi logika seperti valid atau tidak valid, aktif atau tidak aktif." },
            { id: "programming-3", category: "programming", difficulty: "easy", question: "Mengapa komentar kode sebaiknya dipakai seperlunya?", answers: ["Agar menjelaskan bagian yang tidak langsung jelas tanpa membuat kode bising", "Agar semua baris kode menjadi hijau", "Agar program selalu lebih cepat", "Agar tidak perlu testing"], correct: 0, hint: "Komentar bagus membantu pembaca, bukan mengganti kode yang jelas.", explanation: "Komentar paling berguna untuk menjelaskan alasan atau konteks, bukan mengulang hal yang sudah jelas dari kode." },
            { id: "programming-4", category: "programming", difficulty: "easy", question: "Apa tujuan dasar conditional statement seperti if?", answers: ["Menjalankan kode tertentu hanya saat kondisi terpenuhi", "Menyimpan file gambar", "Membuat database baru", "Menghapus semua bug"], correct: 0, hint: "Pikirkan percabangan keputusan.", explanation: "Conditional statement membuat program dapat memilih alur berdasarkan kondisi tertentu." },
            { id: "programming-5", category: "programming", difficulty: "medium", question: "Kapan loop paling tepat digunakan?", answers: ["Saat perlu mengulang instruksi dengan pola tertentu", "Saat ingin membuat warna tombol", "Saat membuat nama file", "Saat menutup browser"], correct: 0, hint: "Cari kebutuhan yang terjadi berkali-kali.", explanation: "Loop membantu menjalankan blok kode berulang kali sampai kondisi tertentu terpenuhi." },
            { id: "programming-6", category: "programming", difficulty: "medium", question: "Apa manfaat memecah kode menjadi function kecil?", answers: ["Kode lebih mudah diuji, dibaca, dan digunakan ulang", "Kode selalu lebih cepat tanpa pengecualian", "Program tidak perlu data", "Semua bug langsung hilang"], correct: 0, hint: "Pikirkan maintainability.", explanation: "Function kecil membuat tanggung jawab kode lebih jelas sehingga mudah diuji, dirawat, dan dipakai ulang." },
            { id: "programming-7", category: "programming", difficulty: "medium", question: "Apa yang biasanya dilakukan proses debugging?", answers: ["Menemukan penyebab error dan memperbaiki perilaku program", "Mengubah semua teks menjadi kapital", "Menghapus dokumentasi", "Membuat logo aplikasi"], correct: 0, hint: "Debugging mencari akar masalah.", explanation: "Debugging bukan hanya menebak perbaikan, tetapi melacak data, alur, dan kondisi yang membuat program gagal." },
            { id: "programming-8", category: "programming", difficulty: "hard", question: "Mengapa asynchronous programming penting pada aplikasi modern?", answers: ["Agar operasi lambat seperti network tidak memblokir alur utama", "Agar semua kode berjalan tanpa urutan", "Agar database tidak dibutuhkan", "Agar CSS bisa dihapus"], correct: 0, hint: "Network request bisa lama.", explanation: "Async membantu aplikasi tetap responsif saat menunggu operasi I/O seperti fetch API, file, atau database." },
            { id: "programming-9", category: "programming", difficulty: "hard", question: "Apa risiko utama global state yang tidak terkendali?", answers: ["Perubahan dari banyak tempat sulit dilacak dan memicu bug tersembunyi", "Semua variabel menjadi lebih aman", "UI otomatis responsif", "Testing menjadi tidak perlu"], correct: 0, hint: "Semakin banyak tempat bisa mengubah state, semakin sulit dilacak.", explanation: "Global state perlu dibatasi atau dikelola jelas agar perubahan data tidak menimbulkan efek samping yang sulit diprediksi." },
            { id: "programming-10", category: "programming", difficulty: "hard", question: "Apa prinsip utama clean code?", answers: ["Kode mudah dipahami, bernama jelas, dan punya tanggung jawab terarah", "Kode harus selalu paling pendek", "Kode harus tanpa function", "Kode harus menyembunyikan semua maksudnya"], correct: 0, hint: "Pembaca kode adalah target utama.", explanation: "Clean code memprioritaskan kejelasan, struktur, nama yang bermakna, dan desain yang mudah dirawat." },
            { id: "programming-11", category: "programming", difficulty: "easy", question: "Apa output dari ekspresi 5 + '5' dalam JavaScript?", answers: ["'55'", "'10'", "Error", "NaN"], correct: 0, hint: "JavaScript akan melakukan konversi tipe data otomatis (coercion).", explanation: "Operator + pada string dan number akan mengakibatkan number dikoersi menjadi string, lalu digabungkan (concatenated)." },
            { id: "programming-12", category: "programming", difficulty: "easy", question: "Di bawah ini yang merupakan struktur data dengan prinsip FIFO (First In First Out) adalah?", answers: ["Queue (Antrean)", "Stack (Tumpukan)", "Array", "Tree"], correct: 0, hint: "Seperti antrean bioskop.", explanation: "Queue (antrean) memproses data yang pertama kali masuk terlebih dahulu, sedangkan Stack menggunakan prinsip LIFO (Last In First Out)." },
            { id: "programming-13", category: "programming", difficulty: "medium", question: "Apa perbedaan utama antara compiler dan interpreter?", answers: ["Compiler menerjemahkan seluruh kode sekaligus, Interpreter menerjemahkan baris demi baris", "Compiler hanya untuk bahasa C, sedangkan interpreter hanya untuk Python", "Compiler tidak menghasilkan file output, interpreter menghasilkan file exe", "Interpreter membuat program berjalan jauh lebih cepat daripada compiler"], correct: 0, hint: "Pikirkan waktu penerjemahan kode.", explanation: "Compiler menerjemahkan seluruh source code menjadi machine code sebelum dijalankan, sedangkan interpreter menerjemahkan dan mengeksekusi instruksi baris demi baris saat program berjalan." },
            { id: "programming-14", category: "programming", difficulty: "medium", question: "Dalam paradigma Object-Oriented Programming (OOP), apa yang dimaksud dengan Inheritance?", answers: ["Kemampuan suatu class untuk mewarisi sifat dan metode dari class lain", "Kemampuan menyembunyikan detail implementasi internal", "Kemampuan membuat objek tanpa class", "Kemampuan mengubah tipe data variabel secara dinamis"], correct: 0, hint: "Konsep pewarisan dalam keluarga.", explanation: "Inheritance (pewarisan) memungkinkan sebuah subclass mewarisi attribute and method dari superclass, mendukung reusability kode." },
            { id: "programming-15", category: "programming", difficulty: "medium", question: "Apakah fungsi dari Git dalam pengembangan perangkat lunak?", answers: ["Melacak perubahan pada kode sumber dan memfasilitasi kolaborasi tim", "Mengompilasi kode program menjadi aplikasi", "Menyimpan data user secara online", "Memperbaiki bug secara otomatis menggunakan AI"], correct: 0, hint: "Berhubungan dengan version control.", explanation: "Git adalah distributed version control system yang mencatat riwayat perubahan file kode dan membantu developer bekerja bersama pada project yang sama." },
            { id: "programming-16", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Time Complexity' dalam analisis algoritma?", answers: ["Representasi jumlah waktu atau langkah yang dibutuhkan algoritma untuk berjalan seiring bertambahnya ukuran input", "Lama waktu yang dibutuhkan developer untuk menulis kode program", "Waktu yang diperlukan CPU untuk melakukan restart", "Kecepatan internet saat mengunduh dependency library"], correct: 0, hint: "Pikirkan performa kode terhadap ukuran data (N).", explanation: "Time complexity (biasanya diukur dengan Big O notation) mengukur bagaimana jumlah operasi/waktu eksekusi suatu algoritma bertumbuh seiring bertambahnya ukuran input data." },
            { id: "programming-17", category: "programming", difficulty: "hard", question: "Manakah penjelasan terbaik mengenai rekursi (recursion) dalam pemrograman?", answers: ["Sebuah fungsi yang memanggil dirinya sendiri sampai mencapai base case", "Sebuah loop yang berjalan tanpa henti (infinite loop)", "Metode untuk mengamankan data rahasia user", "Cara untuk menggabungkan dua file database"], correct: 0, hint: "Memanggil diri sendiri.", explanation: "Rekursi adalah teknik pemrograman di mana sebuah fungsi memanggil dirinya sendiri untuk memecahkan sub-masalah yang lebih kecil, dengan base case sebagai batas berhenti." },
            { id: "programming-18", category: "programming", difficulty: "easy", question: "Mana yang merupakan contoh nama variabel yang valid menurut konvensi camelCase?", answers: ["totalHargaBarang", "total-harga-barang", "TotalHargaBarang", "total_harga_barang"], correct: 0, hint: "Kata pertama huruf kecil, kata berikutnya berawalan huruf besar.", explanation: "Konvensi camelCase diawali dengan huruf kecil, dan huruf pertama kata berikutnya ditulis dengan huruf besar tanpa spasi atau karakter khusus." },
            { id: "programming-19", category: "programming", difficulty: "medium", question: "Dalam OOP, apa arti dari Polymorphism?", answers: ["Satu antarmuka atau metode yang dapat memiliki banyak bentuk tindakan yang berbeda", "Kemampuan membuat objek menjadi tidak dapat diubah (immutable)", "Proses enkripsi data sebelum disimpan", "Membagi program menjadi beberapa server"], correct: 0, hint: "Poly berarti banyak, morph berarti bentuk.", explanation: "Polymorphism memungkinkan objek dari kelas-kelas berbeda merespons pesan atau metode yang sama dengan cara yang sesuai dengan spesifik kelas masing-masing." },
            { id: "programming-20", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Memory Leak'?", answers: ["Kondisi di mana memori yang dialokasikan tidak dibebaskan kembali meskipun sudah tidak digunakan", "Kerusakan fisik pada modul RAM di komputer", "Pencurian data memori oleh hacker pihak ketiga", "Proses pembersihan cache browser secara otomatis"], correct: 0, hint: "Memori terbuang sia-sia dan terus berkurang.", explanation: "Memory leak terjadi saat program mengalokasikan memori dinamis di RAM tetapi gagal membebaskannya (deallocation) setelah selesai digunakan, yang lama-kelamaan dapat menghabiskan memori sistem." },

            { id: "database-1", category: "database", difficulty: "easy", question: "Apa fungsi utama primary key dalam tabel database?", answers: ["Mengidentifikasi setiap baris secara unik", "Menghapus tabel", "Mengubah warna kolom", "Membuat animasi data"], correct: 0, hint: "Satu baris, satu identitas.", explanation: "Primary key memastikan setiap record memiliki identitas unik agar mudah direferensikan." },
            { id: "database-2", category: "database", difficulty: "easy", question: "Apa itu record dalam database relasional?", answers: ["Satu baris data dalam tabel", "Satu warna tombol", "Satu folder gambar", "Satu jenis animasi"], correct: 0, hint: "Tabel punya kolom dan baris.", explanation: "Record adalah satu baris yang berisi nilai untuk kolom-kolom dalam sebuah tabel." },
            { id: "database-3", category: "database", difficulty: "easy", question: "Perintah SQL SELECT digunakan untuk apa?", answers: ["Mengambil data dari tabel", "Menghapus aplikasi", "Mengubah ukuran layar", "Membuat ikon"], correct: 0, hint: "SELECT berkaitan dengan membaca data.", explanation: "SELECT digunakan untuk membaca data dari satu atau lebih tabel sesuai kolom dan filter yang dibutuhkan." },
            { id: "database-4", category: "database", difficulty: "easy", question: "Apa fungsi klausa WHERE dalam SQL?", answers: ["Menyaring baris berdasarkan kondisi", "Membuat tabel selalu kosong", "Mengganti nama database", "Mengurutkan warna UI"], correct: 0, hint: "WHERE adalah filter.", explanation: "WHERE membatasi hasil query hanya pada baris yang memenuhi kondisi tertentu." },
            { id: "database-5", category: "database", difficulty: "medium", question: "JOIN dalam SQL digunakan untuk apa?", answers: ["Menggabungkan data dari beberapa tabel yang saling berelasi", "Mengompres gambar", "Mengubah font", "Mengunci laptop"], correct: 0, hint: "Relasi antar tabel adalah kata kuncinya.", explanation: "JOIN menghubungkan tabel berdasarkan kolom terkait sehingga data bisa dibaca dalam satu hasil query." },
            { id: "database-6", category: "database", difficulty: "medium", question: "Apa tujuan normalisasi database?", answers: ["Mengurangi duplikasi dan menjaga konsistensi data", "Membuat semua tabel menjadi satu kolom", "Menghapus kebutuhan query", "Membuat UI lebih berwarna"], correct: 0, hint: "Normalisasi menata struktur data.", explanation: "Normalisasi memecah data ke struktur yang lebih tepat agar redundansi turun dan update lebih aman." },
            { id: "database-7", category: "database", difficulty: "medium", question: "Apa manfaat transaction dalam database?", answers: ["Menjaga beberapa operasi berhasil semua atau batal semua", "Membuat query selalu cepat", "Mengubah SQL menjadi HTML", "Menghapus kebutuhan backup"], correct: 0, hint: "Pikirkan atomicity.", explanation: "Transaction menjaga integritas data saat beberapa operasi harus dianggap sebagai satu kesatuan." },
            { id: "database-8", category: "database", difficulty: "hard", question: "Mengapa index database perlu dipakai dengan bijak?", answers: ["Index mempercepat baca, tetapi bisa menambah beban tulis dan storage", "Index selalu membuat semua query sempurna", "Index mengganti kebutuhan primary key", "Index hanya untuk desain UI"], correct: 0, hint: "Ada tradeoff antara read dan write.", explanation: "Index dapat mempercepat pencarian, tetapi terlalu banyak index memperlambat insert/update dan memakai ruang tambahan." },
            { id: "database-9", category: "database", difficulty: "hard", question: "Apa penyebab umum query menjadi lambat pada tabel besar?", answers: ["Filter tidak memanfaatkan index dan membaca terlalu banyak baris", "Nama tabel terlalu pendek", "Terlalu banyak komentar CSS", "Tombol submit berwarna biru"], correct: 0, hint: "Perhatikan jumlah baris yang discan.", explanation: "Query lambat sering terjadi karena full scan, join tidak efisien, atau index yang tidak cocok dengan pola filter." },
            { id: "database-10", category: "database", difficulty: "hard", question: "Apa risiko menyimpan data turunan tanpa strategi sinkronisasi?", answers: ["Nilainya bisa tidak konsisten dengan sumber data utama", "Database menjadi tidak bisa dibaca", "Semua query gagal otomatis", "Primary key berubah menjadi string"], correct: 0, hint: "Data yang sama di dua tempat harus dijaga.", explanation: "Denormalisasi bisa berguna untuk performa, tetapi perlu strategi agar data turunan tetap selaras." },
            { id: "database-11", category: "database", difficulty: "easy", question: "Apakah kegunaan utama dari SQL FOREIGN KEY?", answers: ["Menghubungkan baris di satu tabel dengan baris di tabel lainnya", "Membuat tabel baru secara otomatis", "Mengubah tipe data kolom menjadi string", "Menghapus database cadangan"], correct: 0, hint: "Berhubungan dengan relasi antar tabel.", explanation: "Foreign Key adalah kolom yang merujuk ke Primary Key di tabel lain, menjaga integritas referensial antara kedua tabel tersebut." },
            { id: "database-12", category: "database", difficulty: "easy", question: "Apakah kepanjangan dari SQL?", answers: ["Structured Query Language", "Simple Queue List", "System Query Locator", "Sequential Query Log"], correct: 0, hint: "Bahasa terstruktur untuk database.", explanation: "SQL singkatan dari Structured Query Language, bahasa standar untuk memanipulasi dan mengambil data dari database relasional." },
            { id: "database-13", category: "database", difficulty: "medium", question: "Manakah di bawah ini yang merupakan ciri utama database NoSQL (non-relasional) dibanding SQL?", answers: ["Skema data fleksibel atau tanpa skema tetap, mendukung skalabilitas horizontal", "Hanya bisa dijalankan di sistem operasi Linux", "Tidak mendukung penyimpanan data teks", "Selalu menggunakan tabel dengan baris dan kolom yang kaku"], correct: 0, hint: "Pikirkan format dokumen atau key-value yang fleksibel.", explanation: "NoSQL didesain untuk menangani data tidak terstruktur atau semi-terstruktur dengan skema fleksibel dan biasanya lebih mudah diskalakan secara horizontal (menambah server)." },
            { id: "database-14", category: "database", difficulty: "medium", question: "Apakah fungsi dari klausa GROUP BY dalam query SQL?", answers: ["Mengelompokkan baris yang memiliki nilai sama ke dalam baris ringkasan", "Mengurutkan data dari nilai terbesar ke terkecil", "Membatasi jumlah data yang ditampilkan di layar", "Menggabungkan dua tabel tanpa relasi"], correct: 0, hint: "Sering digunakan bersama fungsi agregasi seperti COUNT, SUM, atau AVG.", explanation: "GROUP BY digunakan bersama fungsi agregasi untuk mengelompokkan baris data berdasarkan satu atau beberapa kolom untuk menghasilkan ringkasan data." },
            { id: "database-15", category: "database", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Database Transaction'?", answers: ["Satu unit kerja logis yang berisi satu atau beberapa operasi SQL yang harus sukses semua atau gagal semua", "Proses transfer data database antar perusahaan", "Biaya sewa layanan cloud database per bulan", "Proses ekspor data ke format file Excel"], correct: 0, hint: "Pikirkan konsep 'All or Nothing'.", explanation: "Transaction mengelompokkan beberapa operasi database sehingga jika salah satu gagal, seluruh perubahan dibatalkan (rollback) untuk menjaga konsistensi data." },
            { id: "database-16", category: "database", difficulty: "hard", question: "Apakah kepanjangan dari ACID dalam prinsip database relasional?", answers: ["Atomicity, Consistency, Isolation, Durability", "Access, Control, Index, Data", "Accuracy, Cloud, Integration, Delivery", "Authentication, Cipher, Integrity, Decentralization"], correct: 0, hint: "Menjamin transaksi database yang andal.", explanation: "ACID adalah standar transaksi database: Atomicity (semua atau tidak sama sekali), Consistency (validitas data), Isolation (transaksi tidak saling mengganggu), dan Durability (data permanen setelah commit)." },
            { id: "database-17", category: "database", difficulty: "hard", question: "Dalam indexing database relasional, manakah struktur data yang paling umum digunakan?", answers: ["B-Tree atau B+ Tree", "Stack", "Queue", "Linked List"], correct: 0, hint: "Struktur pohon yang seimbang untuk pencarian cepat.", explanation: "B-Tree/B+ Tree digunakan karena mempertahankan data terurut dan memungkinkan pencarian, akses berurutan, penyisipan, dan penghapusan dalam waktu logaritmik." },
            { id: "database-18", category: "database", difficulty: "easy", question: "Klausa SQL ORDER BY digunakan untuk apa?", answers: ["Mengurutkan hasil query berdasarkan kolom tertentu secara ascending atau descending", "Membatasi baris data yang diambil", "Menghitung jumlah baris data", "Menghapus data duplikat"], correct: 0, hint: "Berkaitan dengan urutan alfabet atau angka.", explanation: "ORDER BY digunakan untuk mengurutkan hasil query, baik secara terkecil-terbesar (ASC) maupun terbesar-terkecil (DESC)." },
            { id: "database-19", category: "database", difficulty: "medium", question: "Manakah database berikut yang termasuk kategori NoSQL Document-Oriented?", answers: ["MongoDB", "MySQL", "PostgreSQL", "SQLite"], correct: 0, hint: "Menggunakan format JSON/BSON untuk menyimpan data.", explanation: "MongoDB menyimpan data dalam dokumen fleksibel mirip JSON, menjadikannya salah satu database NoSQL Document-Oriented terpopuler." },
            { id: "database-20", category: "database", difficulty: "hard", question: "Apa tujuan dari replikasi database (Database Replication)?", answers: ["Menyalin data ke server database lain untuk redundansi, high availability, dan pembagian beban baca", "Menghapus duplikasi data di satu tabel", "Mengubah database relasional menjadi NoSQL", "Meningkatkan kecepatan query write dengan membagi satu baris data"], correct: 0, hint: "Pikirkan backup aktif dan pembagian beban kerja.", explanation: "Replikasi database menyalin data secara real-time ke satu atau lebih server replika untuk memastikan jika server utama mati, aplikasi tetap bisa berjalan (failover)." },

            { id: "design-1", category: "design", difficulty: "easy", question: "Apa tujuan utama wireframe?", answers: ["Menyusun struktur dan alur layar sebelum desain visual detail", "Menghitung pajak aplikasi", "Membuat database production", "Menghapus semua teks"], correct: 0, hint: "Ini tahap rangka awal.", explanation: "Wireframe membantu tim melihat struktur, hirarki, dan alur sebelum masuk ke visual final." },
            { id: "design-2", category: "design", difficulty: "easy", question: "Apa arti visual hierarchy dalam UI?", answers: ["Pengaturan elemen agar pengguna tahu mana yang paling penting", "Daftar warna acak", "Teknik backup database", "Cara mematikan animasi"], correct: 0, hint: "Hierarchy membantu perhatian pengguna.", explanation: "Visual hierarchy memakai ukuran, warna, jarak, dan kontras untuk mengarahkan perhatian." },
            { id: "design-3", category: "design", difficulty: "easy", question: "Mengapa tombol utama biasanya dibuat lebih menonjol?", answers: ["Agar aksi prioritas mudah ditemukan", "Agar semua elemen sama penting", "Agar halaman lebih berat", "Agar teks hilang"], correct: 0, hint: "Primary action perlu jelas.", explanation: "Tombol utama menuntun pengguna ke aksi paling penting dalam konteks layar tersebut." },
            { id: "design-4", category: "design", difficulty: "easy", question: "Apa fungsi spacing dalam layout?", answers: ["Memberi jarak agar informasi mudah dipindai dan tidak terasa sesak", "Mengganti semua ikon", "Membuat server cepat", "Menyimpan password"], correct: 0, hint: "Ruang kosong juga bagian desain.", explanation: "Spacing membantu pengelompokan, keterbacaan, dan ritme visual dalam antarmuka itu." },
            { id: "design-5", category: "design", difficulty: "medium", question: "Apa manfaat usability testing?", answers: ["Menemukan masalah penggunaan dari perilaku pengguna nyata", "Membuat logo otomatis", "Mengganti server", "Memperbesar semua tombol tanpa alasan"], correct: 0, hint: "Uji dengan manusia, bukan asumsi saja.", explanation: "Usability testing memperlihatkan titik bingung, hambatan, dan kebutuhan pengguna saat memakai produk." },
            { id: "design-6", category: "design", difficulty: "medium", question: "Mengapa aksesibilitas penting dalam produk digital?", answers: ["Agar lebih banyak orang bisa memakai produk dengan nyaman", "Agar warna selalu hitam putih", "Agar aplikasi hanya bisa dibuka admin", "Agar tidak perlu desain responsif"], correct: 0, hint: "Tidak semua pengguna memakai perangkat dengan cara yang sama.", explanation: "Aksesibilitas mempertimbangkan kontras, keyboard, screen reader, ukuran teks, dan kebutuhan pengguna yang beragam." },
            { id: "design-7", category: "design", difficulty: "medium", question: "Apa contoh microcopy yang baik?", answers: ["Teks singkat yang menjelaskan aksi atau status dengan jelas", "Paragraf panjang di semua tombol", "Nama variabel database", "Kode CSS untuk shadow"], correct: 0, hint: "Microcopy membantu pengguna memahami apa yang terjadi.", explanation: "Microcopy seperti label tombol, pesan error, dan helper text harus ringkas, jelas, dan sesuai konteks." },
            { id: "design-8", category: "design", difficulty: "hard", question: "Design system yang baik biasanya membantu apa?", answers: ["Konsistensi UI, kecepatan produksi, dan kualitas kolaborasi", "Menghapus kebutuhan riset", "Membuat semua halaman identik total", "Mengganti semua developer"], correct: 0, hint: "Komponen dan aturan yang bisa dipakai bersama.", explanation: "Design system menyediakan komponen, token, dan pedoman agar desain lebih konsisten dan tim lebih efisien." },
            { id: "design-9", category: "design", difficulty: "hard", question: "Mengapa kontras warna harus diuji, bukan hanya dilihat sekilas?", answers: ["Persepsi warna berbeda dan standar aksesibilitas butuh rasio yang cukup", "Karena semua warna pasti gagal", "Karena kontras hanya untuk gambar", "Karena browser tidak mendukung warna"], correct: 0, hint: "Kontras memengaruhi keterbacaan.", explanation: "Uji kontras membantu memastikan teks dapat dibaca oleh pengguna dengan kondisi visual dan perangkat yang berbeda." },
            { id: "design-10", category: "design", difficulty: "hard", question: "Apa risiko membuat UI terlalu dekoratif pada tool produktivitas?", answers: ["Workflow inti bisa lambat dipindai dan aksi penting tenggelam", "Semua pengguna pasti lebih cepat", "Data menjadi lebih akurat", "Backend otomatis aman"], correct: 0, hint: "Tool kerja butuh kejelasan dan efisiensi.", explanation: "Dekorasi yang berlebihan dapat mengganggu pemindaian, prioritas aksi, dan fokus pengguna." },
            { id: "design-11", category: "design", difficulty: "easy", question: "Apakah kegunaan utama dari Figma dalam alur kerja UI/UX?", answers: ["Membuat desain antarmuka, komponen interaktif, dan kolaborasi tim secara real-time", "Menulis kode backend Node.js", "Menguji performa database SQL", "Membuat server host lokal"], correct: 0, hint: "Tool desain berbasis web terpopuler saat ini.", explanation: "Figma adalah aplikasi desain grafis vektor dan prototyping yang berfokus pada kolaborasi real-time untuk tim UI/UX." },
            { id: "design-12", category: "design", difficulty: "easy", question: "Apakah warna merah dalam desain UI paling sering digunakan untuk melambangkan?", answers: ["Aksi berbahaya, error, atau pembatalan (destructive action)", "Status sukses atau penyelesaian tugas", "Warna latar belakang default mode malam", "Tombol navigasi menu utama"], correct: 0, hint: "Pikirkan sinyal bahaya atau peringatan.", explanation: "Merah secara psikologis menarik perhatian kuat dan sering digunakan untuk error, peringatan, atau tombol hapus permanen." },
            { id: "design-13", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Color Contrast Ratio' dalam standar aksesibilitas web?", answers: ["Perbandingan tingkat kecerahan antara teks dan latar belakangnya agar mudah dibaca", "Jumlah kombinasi warna yang digunakan dalam satu halaman", "Kecepatan transisi warna saat tombol di-hover", "Proses kalibrasi warna monitor desainer"], correct: 0, hint: "Membantu pengguna dengan gangguan penglihatan membaca teks Anda.", explanation: "Rasio kontras warna membandingkan luminansi teks dengan latar belakangnya. WCAG menetapkan kontras minimum (misal 4.5:1 untuk teks normal) untuk aksesibilitas yang baik." },
            { id: "design-14", category: "design", difficulty: "medium", question: "Apakah perbedaan utama antara UI (User Interface) dan UX (User Experience)?", answers: ["UI berfokus pada keindahan visual antarmuka, sedangkan UX berfokus pada kenyamanan dan kemudahan pengguna saat memakai aplikasi", "UI adalah coding frontend, UX adalah coding backend", "UI hanya untuk website desktop, UX hanya untuk aplikasi mobile", "UI dikerjakan oleh manajer produk, UX dikerjakan oleh developer"], correct: 0, hint: "Pikirkan aspek 'estetika' vs 'pengalaman/perasaan'.", explanation: "UI mengurusi tata letak, warna, tipografi, dan aset visual (tampilan). UX mengurusi riset pengguna, alur navigasi, struktur informasi, dan kemudahan interaksi (rasa)." },
            { id: "design-15", category: "design", difficulty: "medium", question: "Apakah fungsi dari 'Grid System' dalam desain layout UI?", answers: ["Membantu menyusun elemen visual agar rapi, konsisten, sejajar, dan proporsional", "Membuat grid database untuk menyimpan gambar", "Mempercepat waktu loading asset gambar", "Mengenkripsi file desain sebelum dikirim"], correct: 0, hint: "Struktur garis bantu vertikal dan horizontal.", explanation: "Grid system (seperti 8px grid atau 12-column grid) digunakan untuk menyelaraskan elemen desain secara konsisten di berbagai ukuran layar." },
            { id: "design-16", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan prinsip 'Fitts's Law' dalam UX Design?", answers: ["Waktu untuk menjangkau target tergantung pada ukuran target dan jarak ke target tersebut", "Semakin banyak pilihan yang diberikan, semakin lama pengguna mengambil keputusan", "Desain harus selalu menggunakan warna pastel", "Website harus dimuat kurang dari 3 detik"], correct: 0, hint: "Tombol yang besar dan dekat lebih mudah diklik.", explanation: "Hukum Fitts menyatakan bahwa target yang berukuran besar dan diletakkan di tempat yang mudah dijangkau (seperti pojok layar atau dekat kursor) akan lebih cepat dan mudah diklik oleh pengguna." },
            { id: "design-17", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Heuristic Evaluation'?", answers: ["Metode pemeriksaan kegunaan (usability) sistem berdasarkan aturan desain praktis (heuristics)", "Proses analisis performa server menggunakan algoritma machine learning", "Pengujian kecepatan loading halaman web secara berkala", "Uji coba keamanan server dari serangan siber"], correct: 0, hint: "Mengevaluasi dengan 10 standar emas Usability milik Jakob Nielsen.", explanation: "Evaluasi heuristik adalah metode audit UX di mana ahli mengevaluasi antarmuka produk digital terhadap prinsip-prinsip kegunaan yang sudah diakui umum (seperti 10 Usability Heuristics Jakob Nielsen)." },
            { id: "design-18", category: "design", difficulty: "easy", question: "Apakah kepanjangan dari SVG dalam tipe file aset desain?", answers: ["Scalable Vector Graphics", "Standard Visual Grid", "Simple Vector Template", "System Visual Graphic"], correct: 0, hint: "Gambar vektor yang tidak pecah saat diperbesar.", explanation: "SVG (Scalable Vector Graphics) adalah format file gambar berbasis XML yang dapat diskalakan tanpa kehilangan resolusi atau kualitas visualnya." },
            { id: "design-19", category: "design", difficulty: "medium", question: "Manakah di bawah ini yang menggambarkan prinsip 'Hick's Law'?", answers: ["Waktu yang dibutuhkan untuk mengambil keputusan meningkat seiring bertambahnya jumlah dan kompleksitas pilihan", "Pengguna menghaisu sebagian besar waktu mereka di situs lain", "Elemen yang diletakkan berdekatan dianggap memiliki fungsi serupa", "Desain harus selalu menyembunyikan detail teknis"], correct: 0, hint: "Terlalu banyak pilihan menu membuat pengguna bingung dan lambat memilih.", explanation: "Hukum Hick menyatakan bahwa semakin banyak pilihan yang disajikan kepada pengguna, semakin lama waktu yang mereka butuhkan untuk berinteraksi dan membuat keputusan." },
            { id: "design-20", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Design Tokens'?", answers: ["Variabel visual terkecil (seperti warna, font, spacing) yang disimpan dalam format netral (JSON) untuk menjaga konsistensi di berbagai platform", "Mata uang kripto khusus untuk membayar desainer grafis", "Kunci keamanan untuk membuka file proyek Figma", "Kode promo diskon untuk membeli aset desain premium"], correct: 0, hint: "Menghubungkan variabel desain dengan kode developer secara otomatis.", explanation: "Design Tokens adalah unit keputusan desain atomik (seperti nilai HSL warna atau unit rem ukuran font) yang diekspor sebagai JSON/YAML agar bisa digunakan langsung oleh tim frontend (Web, iOS, Android) untuk menjaga konsistensi desain sistem." },

            { id: "analytics-1", category: "analytics", difficulty: "easy", question: "Apa itu KPI?", answers: ["Ukuran penting untuk menilai pencapaian tujuan", "Nama bahasa pemrograman", "Format gambar", "Jenis tombol navigasi"], correct: 0, hint: "KPI berhubungan dengan target.", explanation: "KPI adalah metrik utama yang dipakai untuk mengevaluasi performa terhadap tujuan tertentu." },
            { id: "analytics-2", category: "analytics", difficulty: "easy", question: "Apa fungsi dashboard analitik?", answers: ["Meringkas metrik penting agar mudah dipantau", "Menulis kode otomatis", "Menghapus database", "Mengganti UI menjadi gelap"], correct: 0, hint: "Dashboard membantu melihat status.", explanation: "Dashboard menyatukan metrik penting agar tim bisa memantau kondisi dan perubahan dengan cepat." },
            { id: "analytics-3", category: "analytics", difficulty: "easy", question: "Apa arti conversion rate?", answers: ["Persentase pengguna yang menyelesaikan aksi target", "Jumlah warna dalam halaman", "Ukuran file gambar", "Durasi animasi tombol"], correct: 0, hint: "Conversion berkaitan dengan aksi target.", explanation: "Conversion rate mengukur proporsi pengguna yang melakukan aksi penting seperti daftar, beli, atau menyelesaikan kuis." },
            { id: "analytics-4", category: "analytics", difficulty: "easy", question: "Apa itu data segmentasi?", answers: ["Membagi data ke kelompok bermakna untuk analisis lebih jelas", "Menghapus semua data kecil", "Mengubah data menjadi gambar", "Menyimpan data tanpa kategori"], correct: 0, hint: "Segmentasi memecah audiens atau data.", explanation: "Segmentasi membantu menemukan pola yang mungkin tertutup jika semua data digabung." },
            { id: "analytics-5", category: "analytics", difficulty: "medium", question: "Mengapa funnel analysis berguna?", answers: ["Melihat titik pengguna banyak berhenti dalam sebuah alur", "Menghapus data duplikat otomatis", "Membuat password", "Mengubah warna chart"], correct: 0, hint: "Perhatikan perjalanan pengguna dari awal sampai akhir.", explanation: "Funnel analysis menunjukkan tahap mana yang kehilangan banyak pengguna sehingga tim tahu prioritas perbaikan." },
            { id: "analytics-6", category: "analytics", difficulty: "medium", question: "Apa tujuan A/B testing?", answers: ["Membandingkan dua varian untuk melihat mana yang lebih efektif", "Membuat dua database identik", "Menghapus kebutuhan data", "Mengganti bahasa coding"], correct: 0, hint: "A dan B adalah dua versi.", explanation: "A/B testing membantu mengambil keputusan berbasis data dengan membandingkan performa dua varian." },
            { id: "analytics-7", category: "analytics", difficulty: "medium", question: "Mengapa data outlier perlu diperiksa?", answers: ["Outlier bisa menunjukkan error, kasus ekstrem, atau insight penting", "Outlier selalu harus dihapus", "Outlier hanya muncul di gambar", "Outlier membuat chart tidak bisa dibuka"], correct: 0, hint: "Nilai ekstrem punya cerita.", explanation: "Outlier tidak otomatis salah. Ia perlu diperiksa karena bisa berasal dari error atau fenomena penting." },
            { id: "analytics-8", category: "analytics", difficulty: "hard", question: "Apa risiko mengambil keputusan hanya dari rata-rata?", answers: ["Rata-rata bisa menyembunyikan outlier dan perbedaan antar segmen", "Rata-rata selalu salah", "Rata-rata hanya untuk UI", "Data tidak bisa dihitung"], correct: 0, hint: "Segmentasi sering membuka cerita yang tertutup.", explanation: "Rata-rata berguna, tetapi dapat menutup variasi penting. Segmentasi, distribusi, dan outlier perlu ikut dilihat." },
            { id: "analytics-9", category: "analytics", difficulty: "hard", question: "Mengapa korelasi tidak otomatis berarti sebab-akibat?", answers: ["Dua metrik bisa bergerak bersama karena faktor lain", "Korelasi selalu palsu", "Sebab-akibat hanya ada di CSS", "Data angka tidak bisa dibandingkan"], correct: 0, hint: "Ada kemungkinan variabel ketiga.", explanation: "Korelasi menunjukkan hubungan, tetapi eksperimen atau analisis lebih lanjut dibutuhkan untuk menyimpulkan kausalitas." },
            { id: "analytics-10", category: "analytics", difficulty: "hard", question: "Apa masalah umum vanity metric?", answers: ["Terlihat bagus tetapi tidak selalu terkait keputusan atau tujuan bisnis", "Tidak bisa divisualisasikan", "Selalu lebih akurat dari KPI", "Hanya berlaku untuk database"], correct: 0, hint: "Metrik cantik belum tentu actionable.", explanation: "Vanity metric bisa membuat performa tampak bagus tanpa memberi arah tindakan yang berarti." },
            { id: "analytics-11", category: "analytics", difficulty: "easy", question: "Apakah kepanjangan dari CAC dalam analisis bisnis?", answers: ["Customer Acquisition Cost", "Customer Active Count", "Click Action Rate", "Company Asset Cost"], correct: 0, hint: "Biaya untuk mendapatkan pelanggan baru.", explanation: "CAC mengukur total biaya pemasaran dan penjualan yang dikeluarkan untuk meyakinkan satu pelanggan baru agar membeli produk Anda." },
            { id: "analytics-12", category: "analytics", difficulty: "easy", question: "Dalam visualisasi data, kapankah pie chart paling tepat digunakan?", answers: ["Untuk membandingkan bagian-bagian kecil yang membentuk satu kesatuan penuh (persentase total)", "Untuk melacak tren data dari waktu ke waktu", "Untuk menunjukkan hubungan korelasi antara dua variabel angka", "Untuk memvisualisasikan data geografi"], correct: 0, hint: "Menunjukkan proporsi bagian dari 100%.", explanation: "Pie chart terbaik untuk menampilkan komposisi statis dari bagian-bagian kecil yang secara kumulatif membentuk 100%." },
            { id: "analytics-13", category: "analytics", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Churn Rate'?", answers: ["Persentase pelanggan yang berhenti berlangganan atau berhenti menggunakan produk dalam jangka waktu tertentu", "Jumlah rata-rata klik yang didapatkan oleh sebuah iklan banner", "Kecepatan loading database saat memproses data transaksi", "Jumlah keuntungan bersih yang didapatkan per hari"], correct: 0, hint: "Berkaitan dengan pelanggan yang pergi/hilang.", explanation: "Churn rate mengukur tingkat kehilangan pelanggan, metrik krusial bagi bisnis berbasis langganan (SaaS) untuk mengukur kepuasan pelanggan." },
            { id: "analytics-14", category: "analytics", difficulty: "medium", question: "Apakah perbedaan utama antara korelasi (correlation) dan kausalitas (causality)?", answers: ["Korelasi menunjukkan hubungan statistik antara dua variabel, sedangkan kausalitas membuktikan bahwa perubahan satu variabel menyebabkan perubahan pada variabel lain", "Korelasi hanya untuk data kualitatif, kausalitas hanya untuk data kuantitatif", "Korelasi selalu benar, kausalitas hanya hipotesis", "Korelasi dikerjakan oleh data analyst, kausalitas dikerjakan oleh developer"], correct: 0, hint: "Ingat pepatah 'Correlation does not imply causation'.", explanation: "Korelasi berarti dua variabel bergerak bersama secara statistik, namun belum tentu salah satunya menyebabkan yang lain terjadi (bisa jadi ada faktor luar/variabel ketiga)." },
            { id: "analytics-15", category: "analytics", difficulty: "medium", question: "Apakah kegunaan utama dari scatter plot dalam analisis data?", answers: ["Melihat pola sebaran dan hubungan korelasi antara dua variabel numerik", "Menampilkan struktur hierarki manajemen perusahaan", "Mengurutkan data kategori dari yang tertinggi", "Menghitung rata-rata nilai matematika"], correct: 0, hint: "Menggunakan koordinat kartesius untuk memplot titik-titik data.", explanation: "Scatter plot menempatkan titik-titik data berdasarkan nilai X dan Y untuk melihat apakah ada hubungan (positif, negatif, atau acak) di antara kedua variabel tersebut." },
            { id: "analytics-16", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'LTV' (Lifetime Value) pelanggan dan mengapa ia penting dibandingkan CAC?", answers: ["Perkiraan total pendapatan yang akan dihasilkan pelanggan selama hubungan bisnis mereka dengan perusahaan; LTV harus lebih tinggi dari CAC agar bisnis profitabel", "Durasi waktu pelanggan membuka aplikasi web; LTV tinggi berarti server lambat", "Jumlah aset komputer yang dipinjamkan ke pelanggan", "Biaya hukum untuk menyelesaikan komplain dari pelanggan"], correct: 0, hint: "Hubungan nilai jangka panjang vs biaya akuisisi.", explanation: "LTV mengukur kontribusi keuangan jangka panjang seorang pelanggan. Rasio LTV:CAC yang sehat (biasanya 3:1) menunjukkan model bisnis berkelanjutan dan menguntungkan." },
            { id: "analytics-17", category: "analytics", difficulty: "hard", question: "Dalam statistika, apakah yang dimaksud dengan 'P-value'?", answers: ["Probabilitas mendapatkan hasil ekstrem yang diamati jika hipotesis nol (H0) benar; digunakan untuk menentukan signifikansi statistik", "Jumlah data outlier yang ditemukan dalam sampel", "Nilai rata-rata dari seluruh populasi data", "Persentase data yang hilang akibat error teknis"], correct: 0, hint: "Nilai batas signifikansi yang biasanya dibandingkan dengan alpha (0.05).", explanation: "P-value mengukur kekuatan bukti melawan hipotesis nol. P-value < 0.05 biasanya dianggap signifikan secara statistik, menolak hipotesis nol untuk mendapat dukungan hipotesis alternatif." },
            { id: "analytics-18", category: "analytics", difficulty: "easy", question: "Apakah kepanjangan dari SQL dalam data analytics?", answers: ["Structured Query Language", "System Query Link", "Simple Quantized Layout", "Standardized Queue Logic"], correct: 0, hint: "Bahasa standar untuk berinteraksi dengan database data.", explanation: "SQL digunakan analis data untuk mengambil, memfilter, dan mengagregasi data dari database relasional sebelum dianalisis." },
            { id: "analytics-19", category: "analytics", difficulty: "medium", question: "Manakah definisi yang tepat untuk 'Cohort Analysis'?", answers: ["Analisis perilaku sekelompok pengguna yang berbagi karakteristik atau pengalaman yang sama dalam rentang waktu tertentu", "Proses pembersihan data dari nilai kosong menggunakan algoritma python", "Metode untuk mengamankan hak akses database", "Penghitungan laba bersih sebelum dipotong pajak"], correct: 0, hint: "Mengelompokkan pengguna berdasarkan bulan pendaftaran mereka.", explanation: "Cohort Analysis membagi pengguna ke dalam kelompok (kohort) berdasarkan tanggal aktivitas awal mereka untuk melihat bagaimana retensi atau perilaku mereka berubah seiring waktu." },
            { id: "analytics-20", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Predictive Analytics'?", answers: ["Penggunaan data historis, algoritma statistik, dan teknik machine learning untuk memprediksi hasil di masa depan", "Laporan ringkasan tentang penjualan perusahaan di bulan lalu", "Sistem pendeteksi virus komputer yang berjalan di server", "Proses mengarsipkan data lama yang sudah tidak aktif ke cold storage"], correct: 0, hint: "Berfokus pada peramalan masa depan (forecasting).", explanation: "Predictive analytics melampaui analisis data deskriptif (apa yang terjadi) untuk memprediksi tren dan perilaku masa depan berdasarkan pola data historis." },

            { id: "web-1", category: "web", difficulty: "easy", question: "Apa fungsi HTML dalam halaman web?", answers: ["Menyusun struktur konten halaman", "Mengatur query database", "Menjalankan server fisik", "Mengenkripsi password"], correct: 0, hint: "HTML adalah kerangka konten.", explanation: "HTML mendefinisikan struktur seperti heading, paragraf, link, form, dan elemen halaman." },
            { id: "web-2", category: "web", difficulty: "easy", question: "Apa fungsi CSS?", answers: ["Mengatur tampilan visual seperti layout, warna, dan spacing", "Menyimpan data permanen", "Mengirim email otomatis", "Membuat primary key"], correct: 0, hint: "CSS bicara soal gaya visual.", explanation: "CSS mengontrol presentasi halaman web, termasuk responsif, animasi, dan komponen visual." },
            { id: "web-3", category: "web", difficulty: "easy", question: "Apa fungsi JavaScript di browser?", answers: ["Membuat halaman interaktif dan merespons aksi pengguna", "Mengganti semua file menjadi gambar", "Mencetak database", "Menghapus kebutuhan HTML"], correct: 0, hint: "Interaksi adalah kata kuncinya.", explanation: "JavaScript memungkinkan validasi form, update UI, fetch data, dan logika interaktif di browser." },
            { id: "web-4", category: "web", difficulty: "easy", question: "Apa arti responsive design?", answers: ["Tampilan menyesuaikan ukuran layar dan perangkat", "Server merespons lebih cepat", "Semua tombol berkedip", "Website hanya untuk desktop"], correct: 0, hint: "Pikirkan mobile dan desktop.", explanation: "Responsive design membuat layout tetap nyaman di berbagai ukuran layar." },
            { id: "web-5", category: "web", difficulty: "medium", question: "Apa kegunaan fetch API?", answers: ["Mengambil atau mengirim data melalui request HTTP", "Menggambar ikon SVG otomatis", "Mengubah font Google", "Membuat file zip"], correct: 0, hint: "Fetch berkaitan dengan network request.", explanation: "Fetch API digunakan untuk berkomunikasi dengan server, biasanya mengambil JSON atau mengirim data." },
            { id: "web-6", category: "web", difficulty: "medium", question: "Mengapa semantic HTML penting?", answers: ["Membantu aksesibilitas, SEO, dan struktur dokumen yang jelas", "Agar CSS tidak perlu ditulis", "Agar semua gambar hilang", "Agar database otomatis terhubung"], correct: 0, hint: "Makna elemen penting.", explanation: "Semantic HTML seperti nav, main, section, dan button memberi makna yang dapat dipahami browser dan assistive tech." },
            { id: "web-7", category: "web", difficulty: "medium", question: "Apa penyebab umum layout shift?", answers: ["Ukuran elemen seperti gambar tidak disiapkan sebelum konten dimuat", "Terlalu banyak primary key", "Nama class terlalu panjang", "Semua link memakai href"], correct: 0, hint: "Layout berubah setelah loading.", explanation: "Layout shift terjadi ketika elemen berubah posisi setelah konten lain dimuat, misalnya gambar tanpa dimensi tetap." },
            { id: "web-8", category: "web", difficulty: "hard", question: "Mengapa event delegation berguna?", answers: ["Satu listener parent bisa menangani banyak child dinamis", "Semua event jadi lebih lambat", "CSS otomatis dibuat", "HTML tidak perlu struktur"], correct: 0, hint: "Parent bisa mendengar klik child.", explanation: "Event delegation memanfaatkan bubbling untuk menangani elemen dinamis tanpa memasang listener satu per satu." },
            { id: "web-9", category: "web", difficulty: "hard", question: "Apa risiko menyimpan token sensitif di localStorage?", answers: ["Token rentan dicuri jika terjadi XSS", "Token otomatis terenkripsi kuat", "Token tidak bisa dibaca JavaScript", "Browser menolak semua localStorage"], correct: 0, hint: "localStorage bisa dibaca JavaScript.", explanation: "Jika aplikasi terkena XSS, script berbahaya dapat membaca localStorage dan mengambil token sensitif." },
            { id: "web-10", category: "web", difficulty: "hard", question: "Apa fungsi lazy loading pada aset web?", answers: ["Menunda pemuatan aset sampai benar-benar dibutuhkan", "Memuat semua aset dua kali", "Menghapus gambar dari DOM", "Membuat CSS tidak berlaku"], correct: 0, hint: "Tidak semua aset harus dimuat di awal.", explanation: "Lazy loading dapat mempercepat load awal dengan menunda gambar atau modul yang belum terlihat." },
            { id: "web-11", category: "web", difficulty: "easy", question: "Apakah fungsi utama dari protokol HTTPS dibanding HTTP biasa?", answers: ["Mengamankan komunikasi data dengan enkripsi SSL/TLS agar tidak bisa diintip pihak luar", "Mempercepat loading website dengan kompresi gambar", "Membuat desain website menjadi responsif otomatis", "Mencegah website mati saat diakses banyak pengunjung"], correct: 0, hint: "Pikirkan keamanan enkripsi data sensitif.", explanation: "HTTPS (Hypertext Transfer Protocol Secure) mengenkripsi seluruh pertukaran data antara browser dan server untuk melindunginya dari intersepsi (eavesdropping)." },
            { id: "web-12", category: "web", difficulty: "easy", question: "Manakah tag HTML yang digunakan untuk membuat link ke halaman lain?", answers: ["<a>", "<link>", "<href>", "<button>"], correct: 0, hint: "Singkatan dari 'anchor'.", explanation: "Tag <a> (anchor) digunakan bersama atribut href untuk membuat hyperlink ke halaman web atau file lain." },
            { id: "web-13", category: "web", difficulty: "medium", question: "Apakah kegunaan utama dari CSS Flexbox?", answers: ["Menyusun tata letak elemen secara satu dimensi (baris atau kolom) agar responsif dan mudah sejajar", "Menghubungkan frontend dengan database relasional", "Mengatur fungsi interaktif seperti pop-up login", "Membuat animasi 3D yang berat di web"], correct: 0, hint: "Solusi layout satu dimensi yang fleksibel.", explanation: "Flexbox (Flexible Box Layout) memudahkan perataan, distribusi ruang, dan penyusunan elemen di dalam container, bahkan saat ukurannya dinamis." },
            { id: "web-14", category: "web", difficulty: "medium", question: "Apakah perbedaan utama antara Cookies, LocalStorage, dan SessionStorage di browser?", answers: ["Cookies dikirim ke server pada setiap request, LocalStorage bertahan selamanya, sedangkan SessionStorage hilang saat tab ditutup", "LocalStorage dikirim ke server, Cookies hanya disimpan di browser lokal", "SessionStorage bertahan selamanya, LocalStorage hilang saat browser ditutup", "Ketiganya memiliki kapasitas penyimpanan yang sama persis yaitu 100 GB"], correct: 0, hint: "Pikirkan masa aktif penyimpanan dan komunikasi dengan server.", explanation: "Cookies digunakan untuk autentikasi dan dikirim ke server. LocalStorage menyimpan data secara permanen di browser (kapasitas ~5-10MB). SessionStorage hanya menyimpan data selama sesi tab aktif." },
            { id: "web-15", category: "web", difficulty: "medium", question: "Apakah kepanjangan dari API dalam konteks web development?", answers: ["Application Programming Interface", "Active Performance Indicator", "Automated Program Integration", "Advanced Protocol Internet"], correct: 0, hint: "Jembatan komunikasi antar aplikasi.", explanation: "API adalah sekumpulan definisi dan protokol yang memungkinkan satu aplikasi perangkat lunak berinteraksi dan berbagi data dengan aplikasi lainnya." },
            { id: "web-16", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan CORS (Cross-Origin Resource Sharing)?", answers: ["Mekanisme keamanan browser untuk membatasi request resource dari origin yang berbeda dari origin situs saat ini", "Proses mengompres file CSS dan JS menjadi ukuran yang sangat kecil", "Sistem distribusi beban server web menggunakan CDN global", "Algoritma enkripsi password yang aman di server backend"], correct: 0, hint: "Browser memblokir fetch API dari domain lain jika header CORS tidak disiapkan.", explanation: "CORS adalah kebijakan keamanan browser (Same-Origin Policy) yang mencegah script berbahaya membaca resource sensitif dari origin (domain/protokol/port) lain kecuali server tujuan mengizinkannya secara eksplisit lewat header HTTP." },
            { id: "web-17", category: "web", difficulty: "hard", question: "Dalam optimasi performa web, apakah yang dimaksud dengan metrik 'LCP' (Largest Contentful Paint)?", answers: ["Waktu yang dibutuhkan browser untuk merender elemen visual terbesar (seperti gambar banner atau teks utama) di layar", "Kecepatan server merespons koneksi internet pertama kali", "Jumlah total bytes file javascript yang diunduh oleh halaman", "Durasi waktu yang diperlukan pengguna untuk berpindah halaman"], correct: 0, hint: "Salah satu metrik Core Web Vitals penting dari Google.", explanation: "LCP mengukur waktu rendering konten utama halaman web. LCP yang baik adalah kurang dari 2.5 detik untuk memberikan pengalaman pengguna yang responsif." },
            { id: "web-18", category: "web", difficulty: "easy", question: "Apakah fungsi dari tag HTML <meta charset='UTF-8'>?", answers: ["Menentukan encoding karakter dokumen agar browser menampilkan teks bahasa dunia dengan benar", "Mengatur warna latar belakang halaman web menjadi transparan", "Menyisipkan file stylesheet eksternal", "Menghubungkan halaman web dengan library JavaScript jQuery"], correct: 0, hint: "Berhubungan dengan encoding teks.", explanation: "UTF-8 mendukung hampir semua karakter tulisan dunia, memastikan browser menampilkan simbol dan alfabet khusus secara akurat." },
            { id: "web-19", category: "web", difficulty: "medium", question: "Manakah status kode HTTP yang menunjukkan bahwa resource tidak ditemukan di server?", answers: ["404 Not Found", "500 Internal Server Error", "200 OK", "302 Found (Redirect)"], correct: 0, hint: "Sangat populer saat halaman web rusak atau hilang.", explanation: "Status 404 adalah kode respons standar HTTP yang menunjukkan bahwa server tidak dapat menemukan berkas yang diminta oleh pengguna." },
            { id: "web-20", category: "web", difficulty: "hard", question: "Apakah perbedaan utama antara Single Page Application (SPA) dan Multi Page Application (MPA)?", answers: ["SPA memuat satu dokumen HTML awal dan memperbarui konten secara dinamis tanpa reload halaman, sedangkan MPA memuat dokumen HTML baru dari server setiap kali pindah halaman", "SPA ditulis dengan Python, MPA ditulis dengan PHP", "SPA hanya mendukung perangkat mobile, MPA mendukung semua perangkat", "SPA tidak bisa memiliki link eksternal, MPA bisa"], correct: 0, hint: "Pikirkan perilaku reload halaman browser saat pindah menu.", explanation: "SPA (seperti aplikasi React/Vue) menawarkan transisi yang lebih mulus dan cepat karena hanya meminta data (JSON) dari server, bukan dokumen HTML utuh seperti MPA tradisional." },

            { id: "cyber-1", category: "cyber", difficulty: "easy", question: "Apa ciri password yang lebih aman?", answers: ["Panjang, unik, dan sulit ditebak", "Sama untuk semua akun", "Berisi nama sendiri saja", "Disimpan di komentar publik"], correct: 0, hint: "Panjang dan unik lebih penting.", explanation: "Password kuat sebaiknya panjang, unik per layanan, dan dikelola dengan password manager bila memungkinkan." },
            { id: "cyber-2", category: "cyber", difficulty: "easy", question: "Apa itu phishing?", answers: ["Upaya menipu pengguna agar memberikan data sensitif", "Teknik mempercepat CSS", "Jenis database relasional", "Metode desain ikon"], correct: 0, hint: "Biasanya lewat pesan palsu.", explanation: "Phishing memancing korban lewat email, chat, atau halaman palsu agar memberikan password, OTP, atau data penting." },
            { id: "cyber-3", category: "cyber", difficulty: "easy", question: "Mengapa update software penting?", answers: ["Sering membawa perbaikan keamanan dan bug", "Agar semua data hilang", "Agar password menjadi pendek", "Agar layar selalu gelap"], correct: 0, hint: "Patch keamanan sering datang lewat update.", explanation: "Update software dapat menutup celah keamanan yang sudah diketahui dan meningkatkan stabilitas." },
            { id: "cyber-4", category: "cyber", difficulty: "easy", question: "Apa tujuan two-factor authentication?", answers: ["Menambah lapisan verifikasi selain password", "Menghapus akun lama", "Membuat UI lebih ramai", "Mengganti username"], correct: 0, hint: "Password bukan satu-satunya bukti.", explanation: "2FA mengurangi risiko akun diambil alih meski password bocor." },
            { id: "cyber-5", category: "cyber", difficulty: "medium", question: "Apa prinsip least privilege?", answers: ["Memberi akses minimum yang dibutuhkan untuk tugas", "Memberi akses admin ke semua orang", "Menghapus semua role", "Membuka database publik"], correct: 0, hint: "Akses secukupnya.", explanation: "Least privilege membatasi dampak kesalahan atau kebocoran dengan memberi izin sesuai kebutuhan saja." },
            { id: "cyber-6", category: "cyber", difficulty: "medium", question: "Mengapa backup perlu diuji restore-nya?", answers: ["Backup belum terbukti berguna sampai bisa dipulihkan", "Agar file backup lebih besar", "Agar password berubah", "Agar query lebih lambat"], correct: 0, hint: "Backup yang tidak bisa dipulihkan tidak banyak membantu.", explanation: "Uji restore memastikan data benar-benar dapat dikembalikan saat insiden terjadi." },
            { id: "cyber-7", category: "cyber", difficulty: "medium", question: "Apa itu data minimization?", answers: ["Mengumpulkan data secukupnya sesuai kebutuhan", "Menghapus semua data penting", "Menyimpan data tanpa izin", "Membuat data tidak bisa dicari"], correct: 0, hint: "Ambil yang perlu saja.", explanation: "Data minimization mengurangi risiko privasi dan keamanan dengan tidak mengumpulkan data berlebihan." },
            { id: "cyber-8", category: "cyber", difficulty: "hard", question: "Apa risiko XSS pada aplikasi web?", answers: ["Script berbahaya dapat berjalan di browser pengguna", "Server selalu mati total", "CSS tidak bisa dimuat", "Database otomatis terenkripsi"], correct: 0, hint: "XSS menyisipkan script.", explanation: "XSS memungkinkan penyerang menjalankan script di konteks situs, mencuri data, atau memanipulasi halaman." },
            { id: "cyber-9", category: "cyber", difficulty: "hard", question: "Mengapa input user harus divalidasi di server juga?", answers: ["Validasi client bisa dilewati atau dimanipulasi", "Server tidak bisa membaca input", "Browser selalu benar", "CSS bisa mengganti database"], correct: 0, hint: "Client bukan sumber kepercayaan.", explanation: "Validasi server wajib karena request bisa dibuat langsung tanpa mengikuti aturan UI di browser." },
            { id: "cyber-10", category: "cyber", difficulty: "hard", question: "Apa manfaat audit log pada sistem penting?", answers: ["Mencatat aktivitas agar insiden dan perubahan bisa ditelusuri", "Menghapus error otomatis", "Mengganti backup", "Membuat semua user admin"], correct: 0, hint: "Log membantu investigasi.", explanation: "Audit log memberi jejak aktivitas penting sehingga tim dapat meninjau perubahan, akses, dan potensi insiden." },
            { id: "cyber-11", category: "cyber", difficulty: "easy", question: "Apakah yang dimaksud dengan VPN (Virtual Private Network)?", answers: ["Layanan yang mengenkripsi lalu lintas internet Anda dan menyembunyikan identitas online Anda dengan merutekannya melalui server aman", "Aplikasi untuk mempercepat koneksi Wi-Fi secara gratis", "Antivirus untuk membersihkan file sampah di komputer", "Database khusus untuk menyimpan password akun media sosial"], correct: 0, hint: "Membuat terowongan enkripsi privat di internet publik.", explanation: "VPN mengamankan koneksi internet Anda dengan mengenkripsi data Anda dan menyembunyikan alamat IP asli Anda untuk menjaga privasi." },
            { id: "cyber-12", category: "cyber", difficulty: "easy", question: "Apakah kepanjangan dari MFA dalam keamanan siber?", answers: ["Multi-Factor Authentication", "Malicious File Analyzer", "Mobile Firewall Access", "Main Frame Auditor"], correct: 0, hint: "Membutuhkan lebih dari sekadar password untuk masuk.", explanation: "MFA adalah metode verifikasi identitas yang mengharuskan pengguna memberikan dua atau lebih faktor verifikasi untuk mendapatkan akses ke akun." },
            { id: "cyber-13", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan serangan Ransomware?", answers: ["Malware yang mengenkripsi file korban dan menuntut pembayaran tebusan untuk kunci dekripsi", "Serangan yang membuat server web mati akibat dibanjiri trafik palsu", "Teknik mencuri informasi kartu kredit lewat form login palsu", "Penyusupan ke ruang server fisik untuk mencuri komputer"], correct: 0, hint: "Ransom berarti tebusan.", explanation: "Ransomware adalah jenis perangkat perusak (malware) berbahaya yang menyandera data komputer dengan enkripsi kuat, lalu memeras korban untuk membayar uang tebusan." },
            { id: "cyber-14", category: "cyber", difficulty: "medium", question: "Apakah perbedaan utama antara enkripsi simetris (symmetric encryption) dan enkripsi asimetris (asymmetric encryption)?", answers: ["Enkripsi simetris menggunakan satu kunci untuk enkripsi dan dekripsi, sedangkan asimetris menggunakan sepasang kunci (kunci publik dan kunci privat)", "Enkripsi simetris hanya untuk teks pendek, asimetris untuk file besar", "Enkripsi simetris tidak aman, asimetris sangat aman", "Enkripsi simetris diproses oleh hardware, asimetris oleh software"], correct: 0, hint: "Jumlah kunci rahasia yang digunakan.", explanation: "Enkripsi simetris lebih cepat tetapi membutuhkan transfer kunci aman. Enkripsi asimetris menyelesaikan masalah distribusi kunci dengan menggunakan Public Key untuk enkripsi dan Private Key untuk dekripsi." },
            { id: "cyber-15", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Social Engineering' dalam keamanan informasi?", answers: ["Teknik manipulasi psikologis untuk membohongi orang agar membocorkan informasi rahasia atau melakukan tindakan tertentu", "Pekerjaan membangun jaringan server yang ramah lingkungan", "Cara membuat postingan media sosial yang cepat viral", "Proses audit hubungan interpersonal di dalam kantor"], correct: 0, hint: "Meretas manusia, bukan meretas sistem komputer langsung.", explanation: "Social engineering menargetkan kerentanan manusia (seperti rasa percaya, takut, atau tergesa-gesa) untuk menipu mereka agar memberikan data login, OTP, atau uang." },
            { id: "cyber-16", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan serangan 'Man-in-the-Middle' (MitM)?", answers: ["Penyerang secara diam-diam mencegat dan mengubah komunikasi antara dua pihak yang percaya mereka terhubung langsung satu sama lain", "Serangan fisik dengan merusak kabel internet bawah laut", "Proses membagi tugas server backend secara adil", "Hacker yang menyamar menjadi staf IT internal perusahaan"], correct: 0, hint: "Pikirkan penyadap di antara pengirim dan penerima.", explanation: "Serangan MitM sering terjadi pada jaringan Wi-Fi publik yang tidak aman, di mana penyerang berada di tengah lalu lintas komunikasi untuk mencuri data sensitif seperti password atau data kartu kredit." },
            { id: "cyber-17", category: "cyber", difficulty: "hard", question: "Manakah deskripsi terbaik untuk prinsip keamanan 'Zero Trust'?", answers: ["Jangan pernah percaya, selalu verifikasi; setiap permintaan akses harus diautentikasi, diotorisasi, dan dienkripsi sebelum diizinkan", "Sistem keamanan yang tidak membutuhkan password sama sekali", "Database yang tidak memiliki aturan hak akses user", "Kepercayaan penuh pada firewall perimeter untuk mengamankan jaringan internal"], correct: 0, hint: "Mengasumsikan jaringan internal sudah disusupi.", explanation: "Model Zero Trust meniadakan anggapan bahwa segala sesuatu di dalam jaringan internal aman. Ia mewajibkan verifikasi ketat untuk setiap perangkat dan pengguna, di mana pun lokasinya." },
            { id: "cyber-18", category: "cyber", difficulty: "easy", question: "Di bawah ini, manakah yang merupakan contoh malware?", answers: ["Virus, Trojan, Worm, dan Spyware", "Windows Defender, Avast, dan Kaspersky", "Chrome, Firefox, dan Safari", "MySQL, MongoDB, dan Oracle"], correct: 0, hint: "Perangkat lunak berbahaya.", explanation: "Malware (malicious software) adalah istilah umum untuk program berbahaya yang dirancang untuk merusak, mengganggu, atau menyusup ke sistem komputer tanpa izin." },
            { id: "cyber-19", category: "cyber", difficulty: "medium", question: "Apakah kegunaan utama dari Firewall dalam sistem jaringan?", answers: ["Memantau dan menyaring lalu lintas jaringan masuk dan keluar berdasarkan aturan keamanan yang ditentukan", "Menghapus virus dan malware yang sudah masuk ke harddisk", "Mempercepat transfer file antar komputer di kantor", "Mengubah IP address komputer menjadi IP address server otomatis"], correct: 0, hint: "Pikirkan pos penjaga gerbang masuk jaringan.", explanation: "Firewall bertindak sebagai penghalang antara jaringan internal tepercaya dan jaringan eksternal yang tidak tepercaya (seperti internet) untuk memblokir akses ilegal." },
            { id: "cyber-20", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan serangan SQL Injection (SQLi) dan bagaimana cara terbaik untuk mencegahnya?", answers: ["Penyisipan kode SQL berbahaya ke input form untuk memanipulasi query database; dicegah dengan Prepared Statements (Parameterized Queries)", "Memasukkan terlalu banyak data ke tabel database; dicegah dengan normalisasi tabel", "Serangan menghapus file backup database; dicegah dengan enkripsi harddisk", "Mengganti password database secara paksa; dicegah dengan two-factor authentication"], correct: 0, hint: "Memisahkan data dari instruksi SQL menggunakan parameterized query.", explanation: "SQLi terjadi saat input pengguna langsung digabungkan ke string SQL. Prepared Statements memisahkan kode SQL dari input data sehingga database memperlakukan input murni sebagai data, bukan perintah yang bisa dieksekusi." },
            
            // Programming (New 21-30)
            { id: "programming-21", category: "programming", difficulty: "easy", question: "Apa fungsi dari indeks array?", answers: ["Mengakses elemen spesifik berdasarkan posisinya mulai dari 0", "Menghitung total elemen secara otomatis", "Mengubah tipe data array menjadi string", "Menghapus data array permanen dari RAM"], correct: 0, hint: "Indeks adalah alamat urutan di dalam laci data.", explanation: "Indeks array digunakan untuk merujuk ke elemen tertentu dalam array, di mana penomoran indeks dimulai dari angka 0." },
            { id: "programming-22", category: "programming", difficulty: "easy", question: "Apa kegunaan utama dari tipe data float atau double?", answers: ["Menyimpan angka desimal (pecahan)", "Menyimpan karakter huruf tunggal", "Menghubungkan program ke internet", "Membuat loop berjalan lebih cepat"], correct: 0, hint: "Pikirkan angka seperti 3.14 atau 0.5.", explanation: "Tipe data float atau double digunakan untuk menyimpan bilangan riil yang memiliki koma atau pecahan desimal." },
            { id: "programming-23", category: "programming", difficulty: "medium", question: "Apa kegunaan dari return statement pada sebuah function?", answers: ["Menghentikan eksekusi function dan mengembalikan suatu nilai ke pemanggilnya", "Mencetak teks ke console browser secara otomatis", "Mendeklarasikan variabel baru di dalam local scope", "Menyalin kode function ke file lain"], correct: 0, hint: "Mengirimkan hasil olahan fungsi kembali ke kode luar.", explanation: "Return statement mengakhiri jalannya blok fungsi dan mengirimkan nilai hasil komputasi kembali ke baris kode yang memanggil fungsi tersebut." },
            { id: "programming-24", category: "programming", difficulty: "medium", question: "Manakah penjelasan terbaik mengenai stack overflow?", answers: ["Kondisi eror saat tumpukan memori penuh akibat pemanggilan rekursi tanpa batas", "Database kelebihan kapasitas data transaksi", "Pencurian bandwidth internet oleh server asing", "Keadaan saat browser mendownload gambar terlalu besar"], correct: 0, hint: "Berhubungan dengan tumpukan memori (call stack) yang kehabisan ruang.", explanation: "Stack overflow terjadi ketika call stack melebihi batas alokasi memorinya, yang paling sering dipicu oleh fungsi rekursif yang tidak memiliki base case (kondisi berhenti) yang benar." },
            { id: "programming-25", category: "programming", difficulty: "medium", question: "Apa perbedaan utama antara runtime error dan syntax error?", answers: ["Syntax error melanggar aturan tata bahasa kode, runtime error terjadi saat program berjalan akibat logika atau data tak terduga", "Syntax error hanya terjadi di JavaScript, runtime error hanya terjadi di database", "Syntax error membuat RAM penuh, runtime error menghapus file kode", "Syntax error diperbaiki oleh browser, runtime error diperbaiki oleh OS"], correct: 0, hint: "Satu adalah kesalahan tata tulis sebelum dijalankan, yang lain adalah kesalahan saat eksekusi.", explanation: "Syntax error dideteksi oleh compiler/parser saat pembacaan kode karena melanggar tata bahasa pemrograman. Runtime error terjadi saat instruksi dijalankan (misal pembagian dengan nol atau mengakses properti null)." },
            { id: "programming-26", category: "programming", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Race Condition' dalam konsep pemrograman multithreading?", answers: ["Kondisi di mana hasil akhir program bergantung pada urutan atau waktu eksekusi thread yang tidak terduga", "Dua programmer menulis kode di file yang sama secara berebutan", "Kecepatan eksekusi kode backend yang lebih lambat dari frontend", "Proses transfer data database yang terhambat akibat antrean jaringan"], correct: 0, hint: "Beberapa thread memodifikasi data bersama secara tidak sinkron.", explanation: "Race condition terjadi ketika dua atau lebih thread mengakses data bersama secara konkuren dan hasil akhirnya ditentukan oleh urutan penjadwalan CPU, memicu bug yang sulit dilacak." },
            { id: "programming-27", category: "programming", difficulty: "hard", question: "Apa fungsi dari Garbage Collector dalam runtime environment pemrograman?", answers: ["Mengidentifikasi dan membebaskan memori yang tidak lagi dirujuk oleh program secara otomatis", "Membersihkan file cache browser secara berkala", "Menghapus kode program yang mengandung bug atau eror", "Mengompres ukuran file gambar di dalam folder project"], correct: 0, hint: "Mengelola memori RAM yang tidak terpakai lagi.", explanation: "Garbage Collector (seperti pada JavaScript V8 atau Java VM) melacak objek di memori dan menghapusnya jika objek tersebut sudah tidak memiliki referensi aktif, mencegah kebocoran memori." },
            { id: "programming-28", category: "programming", difficulty: "easy", question: "Di bawah ini, manakah yang merupakan operator perbandingan logika 'DAN' (AND) dalam JavaScript?", answers: ["&&", "||", "!", "=="], correct: 0, hint: "Membutuhkan kedua kondisi bernilai benar agar menghasilkan true.", explanation: "Operator && adalah operator logika AND yang mengembalikan true hanya jika ekspresi di kiri dan kanannya bernilai benar." },
            { id: "programming-29", category: "programming", difficulty: "medium", question: "Apa yang dimaksud dengan 'Scope' pada variabel?", answers: ["Wilayah atau cakupan kode di mana variabel tersebut dapat diakses dan digunakan", "Ukuran memori RAM yang digunakan oleh suatu variabel", "Waktu yang dibutuhkan variabel untuk melakukan update nilai", "Jenis tipe data yang dapat disimpan di dalam variabel"], correct: 0, hint: "Batasan visibilitas variabel (global vs lokal).", explanation: "Scope menentukan visibilitas atau aksesibilitas variabel di berbagai bagian kode program (seperti block scope, function scope, atau global scope)." },
            { id: "programming-30", category: "programming", difficulty: "hard", question: "Dalam OOP, apa bedanya Class dengan Object?", answers: ["Class adalah cetak biru (blueprint) desain, sedangkan Object adalah wujud nyata (instance) dari class tersebut", "Class digunakan untuk database, Object digunakan untuk tampilan UI", "Class hanya bisa dibuat sekali, Object bisa disalin ribuan kali tanpa class", "Class memperlambat program, Object mempercepat eksekusi memori"], correct: 0, hint: "Satu adalah rancangan di kertas, satu lagi adalah rumah yang sudah jadi.", explanation: "Class mendefinisikan struktur data dan perilaku (metode), sementara Object adalah instansiasi nyata di memori yang dibuat berdasarkan definisi Class tersebut." },

            // Database (New 21-30)
            { id: "database-21", category: "database", difficulty: "easy", question: "Bagaimana cara mengambil seluruh baris data dari tabel bernama 'siswa' menggunakan SQL?", answers: ["SELECT * FROM siswa;", "GET ALL FROM siswa;", "SELECT ALL siswa;", "READ TABLE siswa;"], correct: 0, hint: "Tanda bintang (*) melambangkan semua kolom.", explanation: "Kueri SELECT * FROM nama_tabel digunakan untuk membaca seluruh kolom dan baris yang ada di dalam tabel tersebut." },
            { id: "database-22", category: "database", difficulty: "easy", question: "Apa fungsi dari klausa LIMIT dalam query SQL?", answers: ["Membatasi jumlah baris hasil query yang dikembalikan oleh database", "Membatasi kapasitas memori harddisk untuk database", "Membatasi jumlah karakter yang bisa diinput ke kolom", "Menghapus koneksi database yang sedang idle"], correct: 0, hint: "Membatasi kuantitas data keluaran query.", explanation: "Klausa LIMIT (atau TOP di beberapa sistem) digunakan untuk membatasi jumlah record maksimal yang dikembalikan oleh kueri database." },
            { id: "database-23", category: "database", difficulty: "medium", question: "Manakah kueri SQL yang tepat untuk menghapus baris data di tabel 'guru' yang memiliki id = 5?", answers: ["DELETE FROM guru WHERE id = 5;", "DROP FROM guru WHERE id = 5;", "REMOVE FROM guru WHERE id = 5;", "DELETE WHERE id = 5 FROM guru;"], correct: 0, hint: "Gunakan perintah DELETE dengan filter WHERE.", explanation: "Perintah DELETE FROM guru WHERE id = 5 menghapus baris tertentu yang memenuhi filter, sementara DROP digunakan untuk menghapus seluruh struktur tabel." },
            { id: "database-24", category: "database", difficulty: "medium", question: "Apa perbedaan utama antara INNER JOIN dan LEFT JOIN?", answers: ["INNER JOIN hanya mengambil baris yang cocok di kedua tabel, LEFT JOIN mengambil semua baris tabel kiri dan yang cocok dari tabel kanan", "INNER JOIN menggabungkan kolom secara vertikal, LEFT JOIN secara horizontal", "INNER JOIN lebih lambat dari LEFT JOIN tanpa index", "INNER JOIN hanya untuk database SQL, LEFT JOIN untuk database NoSQL"], correct: 0, hint: "Pikirkan tentang data di tabel sebelah kiri yang tidak memiliki pasangan.", explanation: "INNER JOIN hanya mengembalikan baris yang memiliki kecocokan di kedua tabel. LEFT JOIN mengembalikan seluruh baris dari tabel kiri, serta baris yang cocok dari tabel kanan (diisi NULL jika tidak cocok)." },
            { id: "database-25", category: "database", difficulty: "medium", question: "Apa fungsi utama dari perintah SQL UPDATE?", answers: ["Mengubah atau memperbarui nilai kolom pada baris data yang sudah ada di tabel", "Membuat tabel baru dengan kolom yang diperbarui", "Mengimpor data dari file CSV eksternal", "Menambahkan baris baru ke dalam tabel database"], correct: 0, hint: "Mengedit isi record yang sudah tersimpan.", explanation: "UPDATE digunakan untuk memodifikasi nilai data pada baris yang sudah ada di tabel, biasanya diikuti klausa WHERE untuk membatasi baris yang diubah." },
            { id: "database-26", category: "database", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Database Indexing Cardinality'?", answers: ["Ukuran keunikan nilai data dalam suatu kolom tabel yang di-index", "Jumlah total index yang diizinkan dalam satu database", "Kecepatan database membaca index B-Tree di RAM", "Ukuran file penyimpanan index di harddisk server"], correct: 0, hint: "Semakin banyak nilai unik (seperti ID), semakin tinggi tingkat kardinalitasnya.", explanation: "Kardinalitas merujuk pada keunikan nilai data dalam kolom tertentu. Kolom dengan kardinalitas tinggi (misal email) sangat bagus untuk di-index dibanding kardinalitas rendah (misal gender)." },
            { id: "database-27", category: "database", difficulty: "hard", question: "Apa keuntungan utama menggunakan transaksi database bertingkat (nested transaction / savepoints)?", answers: ["Memungkinkan rollback sebagian operasi tanpa membatalkan seluruh transaksi utama", "Meningkatkan kecepatan query INSERT secara horizontal", "Mengurangi ukuran backup log database secara otomatis", "Menghubungkan database relasional ke server NoSQL secara langsung"], correct: 0, hint: "Gunakan SAVEPOINT untuk membuat titik pemulihan parsial.", explanation: "Dengan SAVEPOINT, pengembang dapat menandai titik tertentu di dalam transaksi dan melakukan ROLLBACK ke savepoint tersebut jika terjadi kegagalan kecil, tanpa membatalkan seluruh transaksi dari awal." },
            { id: "database-28", category: "database", difficulty: "easy", question: "Perintah SQL manakah yang digunakan untuk membuat database baru?", answers: ["CREATE DATABASE nama_database;", "NEW DATABASE nama_database;", "MAKE DATABASE nama_database;", "ADD DATABASE nama_database;"], correct: 0, hint: "CREATE adalah perintah DDL untuk membuat objek baru.", explanation: "CREATE DATABASE digunakan untuk membuat database baru di server manajemen database (DBMS)." },
            { id: "database-29", category: "database", difficulty: "medium", question: "Apa fungsi dari klausa HAVING dalam SQL?", answers: ["Menyaring baris ringkasan hasil GROUP BY berdasarkan kondisi agregat", "Mengurutkan hasil query dari nilai terbesar ke terkecil", "Menyaring baris sebelum data dikelompokkan oleh GROUP BY", "Mencegah nilai duplikat masuk ke database"], correct: 0, hint: "HAVING adalah WHERE untuk fungsi agregasi setelah GROUP BY.", explanation: "Klausa HAVING digunakan untuk memfilter baris hasil agregasi (seperti COUNT atau SUM) yang dihasilkan oleh klausa GROUP BY, karena WHERE tidak bisa digunakan langsung dengan fungsi agregat." },
            { id: "database-30", category: "database", difficulty: "hard", question: "Manakah penjelasan terbaik tentang 'Deadlock' dalam database?", answers: ["Kondisi di mana dua transaksi saling menunggu lock yang dipegang oleh transaksi lainnya, menyebabkan keduanya mandek", "Server database mati akibat korsleting listrik", "Kegagalan kueri akibat tabel yang terkunci permanen karena crash program", "File log transaksi yang sudah penuh dan menolak perintah tulis"], correct: 0, hint: "Transaksi A menunggu Transaksi B, sementara Transaksi B menunggu Transaksi A.", explanation: "Deadlock terjadi ketika Transaksi 1 mengunci Data A dan menunggu kunci Data B, sedangkan Transaksi 2 mengunci Data B dan menunggu kunci Data A. Keduanya saling memblokir selamanya hingga DBMS mendeteksi dan membatalkan salah satunya." },

            // Design (New 21-30)
            { id: "design-21", category: "design", difficulty: "easy", question: "Apakah yang dimaksud dengan 'Color Palette' dalam UI design?", answers: ["Kumpulan warna pilihan yang digunakan secara konsisten di seluruh aplikasi", "Alat untuk mencampur warna cat fisik", "Kode HTML untuk merender gradasi warna", "Metode untuk mengompres asset gambar desain"], correct: 0, hint: "Berhubungan dengan identitas visual dan harmoni warna.", explanation: "Color palette adalah sekumpulan warna yang dipilih secara terencana untuk membangun identitas visual produk dan menjaga konsistensi antarmuka." },
            { id: "design-22", category: "design", difficulty: "easy", question: "Di bawah ini yang merupakan pengertian terdekat dari 'Button Hover State' adalah?", answers: ["Perubahan visual tombol saat kursor mouse diarahkan di atasnya", "Ukuran tombol saat ditekan oleh jari di layar HP", "Waktu yang dibutuhkan tombol untuk memicu fungsi klik", "Deskripsi tombol bagi pembaca layar disabilitas"], correct: 0, hint: "Umpan balik visual sebelum tombol diklik.", explanation: "Hover state memberikan feedback visual kepada pengguna bahwa elemen tersebut interaktif dan siap diklik saat kursor berada di atasnya." },
            { id: "design-23", category: "design", difficulty: "medium", question: "Mengapa penggunaan ruang kosong (whitespace) penting dalam desain antarmuka?", answers: ["Meningkatkan keterbacaan, fokus visual, dan kenyamanan mata pengguna saat memindai konten", "Mengurangi ukuran download file HTML halaman web", "Mempercepat waktu rendering elemen CSS di browser", "Agar developer bisa menulis kode lebih sedikit"], correct: 0, hint: "Memberi ruang bernapas bagi elemen desain.", explanation: "Whitespace (ruang negatif) membantu mengelompokkan elemen terkait, menegaskan visual hierarchy, dan membuat desain tidak terasa penuh atau membingungkan." },
            { id: "design-24", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'User Persona'?", answers: ["Representasi fiktif karakter pengguna target berdasarkan data riset riil", "Daftar hak akses pengguna di dalam database", "Foto profil pengguna yang dipasang di halaman dasbor", "Gaya penulisan microcopy pada tombol aplikasi"], correct: 0, hint: "Profil karakter yang merangkum tujuan, kebutuhan, dan kendala pengguna.", explanation: "User Persona merangkum karakteristik, perilaku, kebutuhan, dan rasa frustrasi dari kelompok pengguna target guna membantu tim desain mengambil keputusan yang berpusat pada manusia." },
            { id: "design-25", category: "design", difficulty: "medium", question: "Apa perbedaan utama antara wireframe low-fidelity dan prototype high-fidelity?", answers: ["Low-fidelity fokus pada struktur kasar tanpa warna, high-fidelity menyertakan detail visual dan interaksi mirip produk asli", "Low-fidelity dibuat di kertas, high-fidelity hanya bisa di-code", "Low-fidelity digunakan untuk backend, high-fidelity untuk frontend", "Low-fidelity tidak diuji ke user, high-fidelity wajib diuji"], correct: 0, hint: "Pikirkan tentang detail visual dan interaktivitas.", explanation: "Wireframe low-fidelity menyusun layout struktural cepat tanpa estetika warna/font. Prototype high-fidelity menyajikan visual final lengkap dengan interaksi tombol, animasi, dan alur transisi nyata." },
            { id: "design-26", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan prinsip 'Aesthetic-Usability Effect'?", answers: ["Pengguna cenderung menganggap desain yang estetis lebih mudah digunakan dibanding yang kurang estetis", "Kecepatan muat halaman web yang cantik selalu lebih cepat", "Desain yang buruk secara visual otomatis ditolak oleh browser", "Desainer harus selalu menggunakan warna hijau untuk status sukses"], correct: 0, hint: "Hubungan keindahan visual dengan persepsi kenyamanan pakai.", explanation: "Aesthetic-Usability Effect menunjukkan bahwa keindahan visual memengaruhi persepsi pengguna sehingga mereka cenderung lebih toleran terhadap kendala kegunaan minor karena menyukai tampilan produk." },
            { id: "design-27", category: "design", difficulty: "hard", question: "Bagaimana cara merancang navigasi untuk memenuhi standar WCAG 2.1 bagi pengguna screen reader?", answers: ["Menyediakan landmark semantik yang jelas dan memastikan urutan fokus keyboard yang logis", "Menghapus semua tombol drop-down navigasi", "Membuat menu navigasi selalu menggunakan ikon gambar tanpa teks", "Mengharuskan pengguna menggunakan mouse untuk berpindah menu"], correct: 0, hint: "Aksesibilitas bagi pengguna tanpa visual/tikus.", explanation: "Standar WCAG mewajibkan struktur HTML semantik (nav, header) dan urutan navigasi keyboard (tabindex) yang logis agar pembaca layar dapat membaca menu dengan teratur." },
            { id: "design-28", category: "design", difficulty: "easy", question: "Apa fungsi utama dari logo dalam bar navigasi atas website?", answers: ["Sebagai identitas merek dan jalan pintas navigasi untuk kembali ke beranda", "Menyimpan file cache halaman web", "Menampilkan animasi selamat datang kepada pengguna", "Menghubungkan halaman web dengan server basis data"], correct: 0, hint: "Konvensi umum saat logo diklik.", explanation: "Secara konvensi, logo di pojok kiri atas navbar berfungsi memperkuat identitas brand dan menjadi tombol pintas instan untuk kembali ke halaman utama (home)." },
            { id: "design-29", category: "design", difficulty: "medium", question: "Apakah yang dimaksud dengan 'Mobile-First Design'?", answers: ["Strategi mendesain untuk layar terkecil (mobile phone) terlebih dahulu sebelum merancang untuk layar yang lebih besar", "Mewajibkan pengguna membuka aplikasi hanya lewat handphone", "Membuat ukuran tombol navigasi selalu sebesar jempol tangan", "Desain yang tidak memerlukan koneksi internet di smartphone"], correct: 0, hint: "Mulai dari batasan ruang terkecil.", explanation: "Mobile-first memaksa desainer fokus pada fitur dan konten paling inti karena keterbatasan ruang layar smartphone, sebelum kemudian memperluas layout ke versi desktop (progressive enhancement)." },
            { id: "design-30", category: "design", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Mental Model' pengguna dalam UX?", answers: ["Asumsi dan keyakinan pengguna tentang cara kerja suatu sistem berdasarkan pengalaman masa lalu mereka", "Algoritma AI untuk memprediksi suasana hati pengguna aplikasi", "Panduan gaya warna yang dibuat oleh desainer produk", "Sistem klasifikasi tingkat fokus pengguna saat melakukan testing"], correct: 0, hint: "Bagaimana pengguna 'berpikir' sistem Anda akan bekerja.", explanation: "Mental model adalah peta kognitif pengguna tentang bagaimana suatu produk digital bekerja. Desain yang baik menyelaraskan antarmuka dengan mental model pengguna agar sistem mudah dipahami tanpa instruksi rumit." },

            // Analytics (New 21-30)
            { id: "analytics-21", category: "analytics", difficulty: "easy", question: "Apakah kepanjangan dari ROI dalam analisis bisnis?", answers: ["Return on Investment", "Rate of Interest", "Real Organization Income", "Revenue of Industry"], correct: 0, hint: "Mengukur efisiensi laba dari investasi yang dikeluarkan.", explanation: "ROI (Return on Investment) adalah rasio keuangan yang membandingkan laba bersih yang diperoleh dengan biaya investasi yang telah dikeluarkan." },
            { id: "analytics-22", category: "analytics", difficulty: "easy", question: "Apa arti dari metrik Bounce Rate pada analisis website?", answers: ["Persentase pengunjung yang langsung keluar setelah membuka satu halaman saja tanpa interaksi lanjutan", "Kecepatan tombol memantul kembali setelah diklik", "Persentase data transaksi database yang gagal disimpan", "Jumlah pengguna yang memblokir notifikasi aplikasi"], correct: 0, hint: "Pengunjung datang lalu langsung pergi.", explanation: "Bounce rate mengukur pengunjung tunggal yang mendarat di halaman web Anda dan langsung meninggalkannya tanpa memicu aksi/klik ke halaman lain di situs tersebut." },
            { id: "analytics-23", category: "analytics", difficulty: "medium", question: "Apa kegunaan dari visualisasi histogram dalam analisis data?", answers: ["Menampilkan distribusi frekuensi dari data numerik kontinu", "Melacak tren penjualan mingguan selama setahun", "Menghubungkan titik koordinat lokasi pelanggan di peta", "Membandingkan persentase kontribusi kategori produk"], correct: 0, hint: "Melihat pola penyebaran dan kerapatan data angka.", explanation: "Histogram mengelompokkan data numerik ke dalam bin (rentang interval) untuk memvisualisasikan bentuk sebaran data, seperti normal, menceng, atau memiliki banyak puncak." },
            { id: "analytics-24", category: "analytics", difficulty: "medium", question: "Bagaimana rumus dasar menghitung Conversion Rate pendaftaran pengguna?", answers: ["(Jumlah pendaftaran / Jumlah total pengunjung unik) * 100", "(Total pengunjung / Jumlah pendaftaran) * 100", "(Jumlah pendaftaran * Biaya server) / 100", "(Pendapatan kotor - Pengeluaran klan) * 100"], correct: 0, hint: "Persentase aksi sukses terhadap total peluang.", explanation: "Conversion rate dihitung dengan membagi jumlah tindakan sukses (konversi) dengan total audiens yang terpapar (pengunjung), lalu dikalikan 100." },
            { id: "analytics-25", category: "analytics", difficulty: "medium", question: "Apakah yang dimaksud dengan Cohort Retention Analysis?", answers: ["Mengamati persentase kelompok pengguna (kohort) yang tetap aktif menggunakan produk seiring berjalannya waktu", "Menghitung rata-rata pengeluaran iklan per bulan", "Menganalisis performa server database di jam-jam sibuk", "Membandingkan rating aplikasi di Android Play Store vs iOS App Store"], correct: 0, hint: "Cohort dihubungkan dengan retensi loyalitas pengguna.", explanation: "Analisis retensi kohort membagi pengguna berdasarkan waktu mulai mereka (misal: pendaftar bulan Januari) lalu melacak berapa persen dari kelompok tersebut yang kembali menggunakan aplikasi di minggu/bulan berikutnya." },
            { id: "analytics-26", category: "analytics", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Statistical Power' dalam eksperimen A/B testing?", answers: ["Probabilitas eksperimen berhasil mendeteksi efek perbedaan yang nyata jika efek tersebut memang ada", "Jumlah total server yang dikerahkan untuk memproses data eksperimen", "Persentase varian B yang lebih unggul dibanding kontrol A", "Kecepatan algoritma statistika dalam menyaring data duplikat"], correct: 0, hint: "Kemampuan menghindari kesalahan Type II (False Negative).", explanation: "Statistical power (kekuatan statistik, biasanya ditargetkan 80%) adalah probabilitas menolak hipotesis nol dengan benar ketika hipotesis alternatif benar. Power rendah rentan gagal mendeteksi perubahan produk yang sebenarnya bermanfaat." },
            { id: "analytics-27", category: "analytics", difficulty: "hard", question: "Apa risiko dari fenomena 'Simpson's Paradox' dalam analisis data bisnis?", answers: ["Sebuah tren yang terlihat konsisten dalam kelompok data terpisah dapat terbalik atau hilang saat data digabungkan", "Grafik visualisasi data mengalami distorsi ukuran di layar mobile", "Rata-rata data bernilai negatif akibat outlier ekstrem", "Algoritma A/B testing terhenti akibat data sampel terlalu sedikit"], correct: 0, hint: "Efek variabel pengganggu (confounding variable) saat agregasi data.", explanation: "Paradoks Simpson terjadi ketika hubungan antara dua variabel berbalik arah atau hilang saat data dianalisis per kelompok dibanding saat seluruh data digabungkan, memicu kesalahan fatal dalam pengambilan keputusan jika analis mengabaikan pengelompokan yang relevan." },
            { id: "analytics-28", category: "analytics", difficulty: "easy", question: "Manakah jenis grafik yang paling cocok untuk menampilkan tren data penjualan bulanan selama 3 tahun terakhir?", answers: ["Line Chart (Grafik Garis)", "Pie Chart (Grafik Lingkaran)", "Scatter Plot", "Treemap"], correct: 0, hint: "Paling baik untuk visualisasi perubahan kontinu terhadap waktu.", explanation: "Line chart sangat efektif untuk menampilkan data deret waktu (time-series) guna melihat arah tren, fluktuasi, dan pola musiman." },
            { id: "analytics-29", category: "analytics", difficulty: "medium", question: "Apakah perbedaan utama antara data kualitatif dan data kuantitatif?", answers: ["Kualitatif berbentuk deskripsi kata/pengalaman, kuantitatif berbentuk angka yang dapat diukur secara statistik", "Kualitatif dianalisis oleh komputer, kuantitatif dianalisis secara manual oleh manusia", "Kualitatif selalu lebih akurat daripada kuantitatif", "Kualitatif disimpan di SQL, kuantitatif disimpan di Excel"], correct: 0, hint: "Kualitas (sifat) vs Kuantitas (jumlah).", explanation: "Data kualitatif bersifat non-numerik (seperti transkrip wawancara) untuk memahami alasan. Data kuantitatif bersifat numerik (seperti jumlah klik) untuk mengukur volume." },
            { id: "analytics-30", category: "analytics", difficulty: "hard", question: "Apakah kegunaan utama dari analisis regresi linear dalam Business Analytics?", answers: ["Memodelkan hubungan dan memprediksi nilai variabel dependen berdasarkan satu atau lebih variabel independen", "Membagi database menjadi beberapa tabel yang ter-normalisasi", "Menghapus duplikasi baris data secara otomatis di database", "Membandingkan preferensi warna tombol UI bagi pengguna baru"], correct: 0, hint: "Membentuk persamaan garis Y = a + bX untuk forecasting.", explanation: "Regresi linear digunakan untuk mempelajari hubungan linier antara variabel sebab (independen) dan variabel akibat (dependen) guna memprediksi nilai variabel akibat di masa depan." },

            // Web (New 21-30)
            { id: "web-21", category: "web", difficulty: "easy", question: "Apakah kepanjangan dari DOM dalam JavaScript browser?", answers: ["Document Object Model", "Digital Output Manager", "Data Object Memory", "Domain Operation Module"], correct: 0, hint: "Representasi struktur pohon halaman web oleh browser.", explanation: "DOM (Document Object Model) adalah API untuk dokumen HTML/XML yang representasikan struktur halaman sebagai pohon objek yang dapat dimanipulasi dengan JavaScript." },
            { id: "web-22", category: "web", difficulty: "easy", question: "Tag HTML manakah yang digunakan untuk menyisipkan gambar di halaman web?", answers: ["<img>", "<picture-file>", "<src>", "<image>"], correct: 0, hint: "Tag tunggal (self-closing) yang membutuhkan atribut src.", explanation: "Tag <img> digunakan untuk menampilkan gambar, dengan atribut src untuk menentukan lokasi file gambar." },
            { id: "web-23", category: "web", difficulty: "medium", question: "Apa kegunaan utama dari atribut CSS 'z-index'?", answers: ["Mengontrol urutan tumpukan elemen secara vertikal di layar (elemen mana yang berada di depan/atas lainnya)", "Mengatur tingkat pembesaran elemen (zoom level)", "Mengubah kecepatan efek animasi transisi elemen", "Mengatur koordinat posisi elemen secara horizontal"], correct: 0, hint: "Menentukan tumpukan sumbu Z elemen yang diposisikan.", explanation: "z-index mengontrol urutan rendering 3D (tumpukan tumpang tindih) elemen web yang memiliki properti position (seperti absolute atau relative)." },
            { id: "web-24", category: "web", difficulty: "medium", question: "Bagaimana cara menghentikan aksi bawaan dari sebuah form submit di browser menggunakan JavaScript?", answers: ["event.preventDefault()", "event.stopPropagation()", "return false;", "form.stopSubmit()"], correct: 0, hint: "Mencegah perilaku bawaan browser (reload halaman).", explanation: "event.preventDefault() menginstruksikan browser untuk tidak menjalankan aksi default (seperti reload halaman saat submit form atau navigasi saat link diklik)." },
            { id: "web-25", category: "web", difficulty: "medium", question: "Apakah yang dimaksud dengan 'CSS Custom Properties'?", answers: ["Variabel CSS yang diawali dengan tanda '--' untuk menyimpan nilai visual yang dapat digunakan ulang", "Font kustom yang diunduh dari server pihak ketiga", "Aturan penulisan layout CSS khusus untuk browser Safari", "Framework CSS kustom yang dibuat sendiri oleh developer"], correct: 0, hint: "Variabel bawaan CSS native.", explanation: "CSS Custom Properties (sering disebut variabel CSS) ditulis dengan format --nama-variabel dan dipanggil menggunakan fungsi var(--nama-variabel), mempermudah manajemen warna dan ukuran." },
            { id: "web-26", category: "web", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Hydration' dalam framework rendering web modern?", answers: ["Proses melampirkan event listener JavaScript ke HTML statis yang di-render oleh server agar menjadi interaktif di browser", "Mengompres script JS agar ukurannya lebih ringan saat diunduh", "Proses membersihkan memory browser dari cache file gambar lama", "Menghubungkan aplikasi frontend ke database SQL secara langsung"], correct: 0, hint: "Menghidupkan HTML mati yang dikirim dari server.", explanation: "Dalam SSR (Server-Side Rendering) atau SSG (Static Site Generation), server mengirimkan halaman HTML statis tanpa event listener. Hydration adalah proses di sisi client di mana library/framework (seperti React) memetakan DOM dan mengaktifkan interaktivitas JavaScript-nya." },
            { id: "web-27", category: "web", difficulty: "hard", question: "Bagaimana cara kerja Service Worker dalam Progressive Web App (PWA)?", answers: ["Berjalan sebagai script latar belakang (thread terpisah) untuk mengelola cache jaringan, mendukung offline, dan push notification", "Mempercepat kueri database SQL dengan kompresi data JSON", "Mengubah tampilan stylesheet CSS secara otomatis sesuai resolusi layar", "Mengamankan password pengguna di server hosting"], correct: 0, hint: "Proxy jaringan di browser yang berjalan di luar thread UI utama.", explanation: "Service Worker adalah script yang berjalan di latar belakang browser, bertindak sebagai proxy jaringan yang dapat memotong request, menyajikan konten dari cache saat offline, serta menerima push notification." },
            { id: "web-28", category: "web", difficulty: "easy", question: "Manakah deklarasi DOCTYPE yang benar untuk HTML5?", answers: ["<!DOCTYPE html>", "<!DOCTYPE HTML5>", "<!DOCTYPE html PUBLIC '-//W3C//DTD HTML 5.0//EN'>", "<html>"], correct: 0, hint: "Deklarasi modern yang sangat pendek.", explanation: "Deklarasi <!DOCTYPE html> di awal dokumen memberi tahu browser bahwa dokumen tersebut ditulis menggunakan standar HTML5." },
            { id: "web-29", category: "web", difficulty: "medium", question: "Apakah fungsi utama dari CSS Media Query?", answers: ["Menerapkan aturan gaya CSS yang berbeda berdasarkan karakteristik perangkat, seperti lebar layar browser", "Memutar file audio atau video secara langsung di dalam kode CSS", "Menghubungkan file stylesheet eksternal ke dalam dokumen HTML", "Mengirimkan data analitik lebar layar ke server backend"], correct: 0, hint: "Kunci utama pembuatan layout responsif (responsive web design).", explanation: "Media Query memungkinkan kita menetapkan breakpoint (misal: @media (max-width: 768px)) untuk mengubah tata letak halaman web agar optimal di layar smartphone, tablet, maupun monitor desktop." },
            { id: "web-30", category: "web", difficulty: "hard", question: "Apakah perbedaan utama antara SSR (Server-Side Rendering) dan CSR (Client-Side Rendering)?", answers: ["SSR membuat HTML lengkap di server sebelum dikirim ke browser, CSR mengirimkan dokumen kosong dan merender konten di browser lewat JavaScript", "SSR ditulis dengan Python, CSR ditulis dengan PHP", "SSR tidak mendukung optimasi SEO, CSR sangat ramah SEO", "SSR memuat data lebih lambat pada transisi halaman dibanding CSR"], correct: 0, hint: "Pikirkan di mana proses pembentukan HTML dilakukan.", explanation: "Pada SSR, server merender HTML lengkap berisi data sehingga browser langsung menampilkannya (bagus untuk SEO & FCP). Pada CSR, browser menerima HTML kosong, mengunduh file JS raksasa, lalu JS tersebut baru merender antarmuka di sisi client." },

            // Cyber (New 21-30)
            { id: "cyber-21", category: "cyber", difficulty: "easy", question: "Apakah yang dimaksud dengan virus komputer?", answers: ["Program berbahaya yang mereplikasi dirinya sendiri dengan menyisipkan kode ke file atau program lain", "Kerusakan fisik pada kabel monitor akibat panas berlebih", "Pesan spam penawaran iklan yang muncul di email", "Kondisi saat RAM komputer penuh akibat menjalankan game berat"], correct: 0, hint: "Menyebar dengan menempel pada inang/program lain.", explanation: "Virus komputer adalah jenis malware yang membutuhkan program inang aktif untuk menyebar dan menginfeksi file lain di sistem komputer." },
            { id: "cyber-22", category: "cyber", difficulty: "easy", question: "Mengapa kita tidak boleh menuliskan password di selembar kertas yang ditempel di monitor?", answers: ["Karena kertas tersebut dapat dilihat dan dibaca dengan mudah oleh siapa saja yang lewat (shoulder surfing)", "Karena tinta kertas dapat merusak layar monitor fisik", "Karena browser tidak bisa membaca password dari kertas", "Karena password menjadi tidak valid jika ditulis manual"], correct: 0, hint: "Keamanan fisik dari pandangan orang lain di sekitar.", explanation: "Menempelkan password secara fisik di tempat terbuka melanggar prinsip keamanan dasar karena siapa pun yang memiliki akses fisik ke ruangan tersebut dapat mencuri kredensial Anda." },
            { id: "cyber-23", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan kerentanan CSRF (Cross-Site Request Forgery)?", answers: ["Serangan yang menipu browser korban yang ter-autentikasi untuk mengirimkan request berbahaya tanpa izin ke aplikasi web", "Penyisipan skrip JavaScript berbahaya ke dalam database aplikasi", "Proses menebak password admin secara berulang-ulang menggunakan bot", "Menghapus database server dengan memotong jalur koneksi SSL"], correct: 0, hint: "Memanfaatkan kredensial aktif korban (seperti cookie sesi) untuk melakukan aksi ilegal.", explanation: "CSRF mengeksploitasi kepercayaan situs web terhadap browser pengguna. Penyerang memicu browser korban untuk mengirimkan request (misal transfer dana atau ganti password) ke aplikasi web target tempat korban sudah login." },
            { id: "cyber-24", category: "cyber", difficulty: "medium", question: "Apa fungsi utama dari sertifikat SSL/TLS pada sebuah website?", answers: ["Membuktikan identitas kepemilikan website dan mengaktifkan koneksi HTTPS terenkripsi", "Mempercepat waktu loading asset gambar halaman web", "Mencegah penyerang menyalin artikel buatan kita", "Memastikan database SQL tidak bisa menerima input kosong"], correct: 0, hint: "Mengubah ikon gembok di browser menjadi terkunci.", explanation: "SSL/TLS memverifikasi bahwa server web adalah pemilik sah domain tersebut dan mengenkripsi seluruh pertukaran data antara browser dan server guna mencegah intersepsi." },
            { id: "cyber-25", category: "cyber", difficulty: "medium", question: "Mengapa kita harus berhati-hati saat menggunakan jaringan WiFi publik tanpa password di bandara atau kafe?", answers: ["Trafik data kita berisiko diintip dan dicuri oleh penyerang menggunakan serangan Man-in-the-Middle", "Kapasitas RAM handphone kita bisa cepat habis otomatis", "WiFi tanpa password selalu memiliki kecepatan unduh yang sangat lambat", "Browser kita akan memblokir seluruh akses ke website HTTPS"], correct: 0, hint: "Jaringan tidak terenkripsi memungkinkan penyadapan paket data.", explanation: "WiFi publik tanpa password tidak mengenkripsi paket data lokal. Penyerang di jaringan yang sama dapat merekam aktivitas internet Anda, menyadap token login, atau membelokkan domain (DNS poisoning)." },
            { id: "cyber-26", category: "cyber", difficulty: "hard", question: "Apakah yang dimaksud dengan 'Salt' dalam proses penyimpanan hashing password?", answers: ["Nilai acak unik yang digabungkan dengan password sebelum di-hash untuk mencegah serangan Rainbow Table", "Bumbu dapur untuk membersihkan debu fisik pada server hosting", "Kunci enkripsi asimetris yang dibagikan ke browser pengguna", "Proses kompresi file database agar hemat storage"], correct: 0, hint: "Menjamin hash unik meskipun dua pengguna memiliki password yang sama.", explanation: "Salt ditambahkan ke password sebelum dimasukkan ke fungsi hash. Ini memastikan bahwa meskipun dua pengguna memiliki password yang sama (misal: 'rahasia123'), nilai hash yang disimpan di database akan berbeda, sehingga mempersulit peretas menggunakan tabel pencarian hash pra-hitung (Rainbow Tables)." },
            { id: "cyber-27", category: "cyber", difficulty: "hard", question: "Bagaimana cara kerja serangan 'Buffer Overflow'?", answers: ["Menulis data melebihi kapasitas memori buffer, menimpa alamat instruksi eksekusi berikutnya untuk menjalankan kode penyerang", "Mengirimkan email spam dalam jumlah besar ke inbox server korporat", "Memutus kabel listrik utama datacenter untuk merusak harddisk", "Mengisi tabel database SQL dengan baris data kosong secara terus-menerus"], correct: 0, hint: "Melampaui batas alokasi variabel memori di stack/heap.", explanation: "Buffer overflow terjadi ketika program menulis data ke buffer memori melebihi ukuran alokasi aslinya. Sisa data menimpa memori sebelahnya, termasuk instruksi pointer (EIP), memungkinkan penyerang mengarahkan program untuk mengeksekusi kode berbahaya (shellcode) mereka." },
            { id: "cyber-28", category: "cyber", difficulty: "easy", question: "Apa kegunaan dari software antivirus di komputer?", answers: ["Mendeteksi, memblokir, dan membersihkan infeksi malware atau file berbahaya", "Membuat kecepatan render animasi 3D lebih cepat", "Mencegah komputer dari kerusakan akibat jatuh", "Membantu melacak lokasi laptop jika hilang dicuri"], correct: 0, hint: "Melindungi dari perangkat lunak berbahaya.", explanation: "Antivirus memindai file dan memori sistem untuk mendeteksi tanda tangan (signature) malware atau pola perilaku mencurigakan guna melindungi sistem dari kerusakan." },
            { id: "cyber-29", category: "cyber", difficulty: "medium", question: "Apakah yang dimaksud dengan 'DDoS Attack'?", answers: ["Serangan membanjiri server dengan jutaan request palsu secara serentak dari banyak perangkat agar server down", "Menebak password user dengan kamus kata secara otomatis", "Pencurian fisik harddisk dari ruang server perusahaan", "Menyalin seluruh source code website secara diam-diam"], correct: 0, hint: "Distributed Denial of Service.", explanation: "DDoS membanjiri bandwidth atau sumber daya server target menggunakan jaringan komputer terinfeksi (Botnet) secara tersebar, menyebabkan layanan tidak bisa diakses pengguna sah." },
            { id: "cyber-30", category: "cyber", difficulty: "hard", question: "Dalam kriptografi, apakah perbedaan utama antara symmetric key dan asymmetric key?", answers: ["Symmetric menggunakan satu kunci rahasia untuk enkripsi dan dekripsi, asymmetric menggunakan sepasang kunci (publik dan privat)", "Symmetric hanya untuk data teks, asymmetric hanya untuk file biner", "Symmetric dijalankan di CPU, asymmetric dijalankan di GPU", "Symmetric kunci publiknya disebarkan ke publik, asymmetric kunci privatnya disebarkan ke publik"], correct: 0, hint: "Jumlah kunci rahasia yang terlibat dalam proses enkripsi/dekripsi.", explanation: "Enkripsi simetris menggunakan kunci rahasia yang sama oleh pengirim dan penerima (cepat, cocok untuk data besar). Enkripsi asimetris menggunakan Public Key untuk mengenkripsi dan Private Key yang berpasangan untuk mendekripsi (aman untuk pertukaran kunci)." }
        ];
